// AUTO-GENERATED by scripts/build-workflow.js from src/core/. Edit src/core/, then run `npm run build:workflow`.
const crypto = require('crypto');

// ---- src/core/config.js ----
/**
 * Configuration shared by the Node.js runtime and the n8n workflow.
 *
 * Fail-safe rules:
 * - DRY_RUN and SANDBOX_MODE stay true unless explicitly set to false/0/no/off.
 * - Values like "your_..._here" count as "not configured".
 * - DOC_PROVIDER defaults to "stub": no document is created anywhere.
 * - Client-facing Slack nudges are off unless CLIENT_NUDGES_ENABLED=true.
 *
 * Embedded verbatim into the n8n Code nodes by scripts/build-workflow.js:
 * top-level names must be unique across src/core/.
 */

const MAP_PLACEHOLDER_RE = /^(?:|your_[a-z0-9_]*_here|changeme|change_me|placeholder|x{3,})$/i;

const DEFAULT_MILESTONE_TEMPLATE = [
  {
    key: 'kickoff',
    name: 'MAP Kickoff & Success Criteria',
    anchor: 'start',
    offsetBusinessDays: 2,
    owner: 'both',
    internalRole: 'ae',
    clientRole: 'champion',
    description: 'Agree on the evaluation scope, success criteria and the dates in this plan.',
  },
  {
    key: 'technical_review',
    name: 'Technical Review',
    anchor: 'close',
    offsetBusinessDays: 25,
    owner: 'client',
    internalRole: 'se',
    clientRole: 'technical',
    description: 'Technical validation of integrations, data flows and architecture fit.',
  },
  {
    key: 'security_audit',
    name: 'Security Audit',
    anchor: 'close',
    offsetBusinessDays: 20,
    owner: 'client',
    internalRole: 'se',
    clientRole: 'security',
    description: 'Security questionnaire, documentation review and any vendor risk assessment.',
  },
  {
    key: 'final_proposal',
    name: 'Final Proposal',
    anchor: 'close',
    offsetBusinessDays: 15,
    owner: 'internal',
    internalRole: 'ae',
    clientRole: 'economic_buyer',
    description: 'Final commercial proposal reflecting the agreed scope.',
  },
  {
    key: 'legal_procurement',
    name: 'Legal & Procurement',
    anchor: 'close',
    offsetBusinessDays: 8,
    owner: 'client',
    internalRole: 'deal_desk',
    clientRole: 'procurement',
    description: 'Contract redlines, vendor onboarding and purchase order.',
  },
  {
    key: 'contract_signature',
    name: 'Contract Signature',
    anchor: 'close',
    offsetBusinessDays: 0,
    owner: 'client',
    internalRole: 'ae',
    clientRole: 'economic_buyer',
    description: 'Signature by the authorised signatory.',
  },
];

function isPlaceholderSetting(value) {
  if (value === undefined || value === null) return true;
  return MAP_PLACEHOLDER_RE.test(String(value).trim());
}

/** true/1/yes/on -> true, false/0/no/off -> false, anything else -> the default. */
function readFlag(value, defaultValue) {
  if (value === undefined || value === null) return defaultValue;
  const v = String(value).trim().toLowerCase();
  if (['true', '1', 'yes', 'on'].includes(v)) return true;
  if (['false', '0', 'no', 'off'].includes(v)) return false;
  return defaultValue;
}

function readInt(value, fallback) {
  const n = Number.parseInt(String(value ?? ''), 10);
  return Number.isFinite(n) && n >= 0 ? n : fallback;
}

function readList(value, fallback = []) {
  if (value === undefined || value === null || String(value).trim() === '') return fallback;
  return String(value).split(',').map((s) => s.trim()).filter(Boolean);
}

function readJson(value, fallback) {
  if (value === undefined || value === null || String(value).trim() === '') return fallback;
  try {
    return JSON.parse(value);
  } catch {
    return { __invalidJson: true };
  }
}

function validateMilestoneTemplate(template) {
  const errors = [];
  if (!Array.isArray(template) || !template.length) return ['milestone template must be a non-empty array'];
  const keys = new Set();
  template.forEach((m, i) => {
    const where = `milestone[${i}]`;
    if (!m || typeof m !== 'object') {
      errors.push(`${where} must be an object`);
      return;
    }
    if (!/^[a-z][a-z0-9_]{1,30}$/.test(String(m.key || ''))) errors.push(`${where}.key must be lowercase snake_case (2-31 chars)`);
    if (keys.has(m.key)) errors.push(`${where}.key "${m.key}" is duplicated`);
    keys.add(m.key);
    if (!m.name) errors.push(`${where}.name is required`);
    if (!['start', 'close'].includes(m.anchor)) errors.push(`${where}.anchor must be "start" or "close"`);
    if (!Number.isInteger(m.offsetBusinessDays) || m.offsetBusinessDays < 0 || m.offsetBusinessDays > 250) {
      errors.push(`${where}.offsetBusinessDays must be an integer from 0 to 250`);
    }
    if (!['client', 'internal', 'both'].includes(m.owner)) errors.push(`${where}.owner must be client, internal or both`);
  });
  return errors;
}

function loadMapConfig(env = {}) {
  const read = (key, fallback = '') => {
    const value = env[key];
    return value === undefined || value === null ? fallback : String(value).trim();
  };
  const docProvider = read('DOC_PROVIDER', 'stub').toLowerCase();
  const template = readJson(read('MILESTONE_TEMPLATE_JSON'), DEFAULT_MILESTONE_TEMPLATE);
  return {
    dryRun: readFlag(env.DRY_RUN, true),
    sandboxMode: readFlag(env.SANDBOX_MODE, true),
    timezoneNote: read('BUSINESS_TIMEZONE_LABEL', 'UTC'),
    webhook: {
      secret: read('N8N_WEBHOOK_SECRET'),
      secretHeader: read('WEBHOOK_SECRET_HEADER', 'x-webhook-secret').toLowerCase(),
      maxBodyBytes: readInt(env.WEBHOOK_MAX_BODY_BYTES, 262144),
    },
    trigger: {
      stageIds: readList(env.TRIGGER_STAGE_IDS, ['presentationscheduled']),
      regenerateExisting: readFlag(env.REGENERATE_EXISTING_MAP, false),
    },
    schedule: {
      holidays: readList(env.HOLIDAYS),
      template,
      minRunwayBusinessDays: readInt(env.MIN_RUNWAY_BUSINESS_DAYS, 5),
    },
    document: {
      provider: ['stub', 'google_docs', 'notion'].includes(docProvider) ? docProvider : 'invalid',
      sellerCompanyName: read('SELLER_COMPANY_NAME', 'Your Company'),
      includeAmount: readFlag(env.MAP_INCLUDE_AMOUNT, false),
      includeContactEmails: readFlag(env.MAP_INCLUDE_CONTACT_EMAILS, false),
      stubBaseUrl: read('STUB_DOC_BASE_URL', 'https://docs.example.com/maps'),
      internalRoleLabels: {
        ae: 'Account Executive',
        se: 'Solutions Engineer',
        deal_desk: 'Deal Desk',
        ...(readJson(read('INTERNAL_ROLE_LABELS_JSON'), {}) || {}),
      },
      google: {
        serviceAccountJson: read('GOOGLE_SERVICE_ACCOUNT_JSON'),
        folderId: read('GOOGLE_DRIVE_FOLDER_ID'),
        sandboxFolderId: read('GOOGLE_SANDBOX_FOLDER_ID'),
        scope: read('GOOGLE_DRIVE_SCOPE', 'https://www.googleapis.com/auth/drive.file'),
      },
      notion: {
        token: read('NOTION_API_TOKEN'),
        databaseId: read('NOTION_DATABASE_ID'),
        sandboxDatabaseId: read('NOTION_SANDBOX_DATABASE_ID'),
        titleProperty: read('NOTION_TITLE_PROPERTY', 'Name'),
        version: read('NOTION_API_VERSION', '2022-06-28'),
      },
    },
    hubspot: {
      token: read('HUBSPOT_PRIVATE_APP_TOKEN'),
      portalId: read('HUBSPOT_PORTAL_ID'),
      sandboxPortalId: read('HUBSPOT_SANDBOX_PORTAL_ID'),
      baseUrl: read('HUBSPOT_BASE_URL', 'https://api.hubapi.com'),
      appBaseUrl: read('HUBSPOT_APP_BASE_URL', 'https://app.hubspot.com'),
    },
    slack: {
      botToken: read('SLACK_BOT_TOKEN'),
      channelId: read('SLACK_CHANNEL_ID'),
      webhookUrl: read('SLACK_WEBHOOK_URL'),
      sandboxChannelId: read('SLACK_SANDBOX_CHANNEL_ID'),
      sandboxWebhookUrl: read('SLACK_SANDBOX_WEBHOOK_URL'),
      ownerSlackMap: readJson(read('OWNER_SLACK_MAP_JSON'), {}) || {},
      clientNudgesEnabled: readFlag(env.CLIENT_NUDGES_ENABLED, false),
      announceNewMaps: readFlag(env.ANNOUNCE_NEW_MAPS, true),
    },
    monitor: {
      nudgeCooldownDays: readInt(env.NUDGE_COOLDOWN_DAYS, 6),
      dueSoonBusinessDays: readInt(env.DUE_SOON_BUSINESS_DAYS, 3),
      maxDeals: readInt(env.MONITOR_MAX_DEALS, 500),
    },
  };
}

function validateMapConfig(config) {
  const errors = [];
  const warnings = [];
  const live = !config.dryRun;
  if (config.schedule.template && config.schedule.template.__invalidJson) errors.push('MILESTONE_TEMPLATE_JSON is not valid JSON');
  else errors.push(...validateMilestoneTemplate(config.schedule.template));
  if (config.document.provider === 'invalid') errors.push('DOC_PROVIDER must be stub, google_docs or notion');
  for (const h of config.schedule.holidays) if (!/^\d{4}-\d{2}-\d{2}$/.test(h)) errors.push(`HOLIDAYS entry "${h}" must be YYYY-MM-DD`);
  if (!config.trigger.stageIds.length) errors.push('TRIGGER_STAGE_IDS must list at least one deal stage ID');
  if (isPlaceholderSetting(config.webhook.secret)) {
    if (live) errors.push('N8N_WEBHOOK_SECRET is missing or a placeholder');
    else warnings.push('N8N_WEBHOOK_SECRET is a placeholder: webhook authentication is skipped in dry run');
  }
  if (live) {
    if (isPlaceholderSetting(config.hubspot.token)) errors.push('HUBSPOT_PRIVATE_APP_TOKEN is missing or a placeholder');
    if (config.document.provider === 'stub') warnings.push('DOC_PROVIDER=stub: deals receive a placeholder MAP URL');
    if (config.document.provider === 'google_docs') {
      if (isPlaceholderSetting(config.document.google.serviceAccountJson)) errors.push('GOOGLE_SERVICE_ACCOUNT_JSON is required for DOC_PROVIDER=google_docs');
      const folder = config.sandboxMode ? config.document.google.sandboxFolderId : config.document.google.folderId;
      if (isPlaceholderSetting(folder)) errors.push(config.sandboxMode ? 'GOOGLE_SANDBOX_FOLDER_ID is required in SANDBOX_MODE' : 'GOOGLE_DRIVE_FOLDER_ID is required');
    }
    if (config.document.provider === 'notion') {
      if (isPlaceholderSetting(config.document.notion.token)) errors.push('NOTION_API_TOKEN is required for DOC_PROVIDER=notion');
      const db = config.sandboxMode ? config.document.notion.sandboxDatabaseId : config.document.notion.databaseId;
      if (isPlaceholderSetting(db)) errors.push(config.sandboxMode ? 'NOTION_SANDBOX_DATABASE_ID is required in SANDBOX_MODE' : 'NOTION_DATABASE_ID is required');
    }
    if (!config.sandboxMode) warnings.push('SANDBOX_MODE=false and DRY_RUN=false: production HubSpot, documents and Slack are modified');
  }
  return { errors, warnings };
}

// ---- src/core/milestones.js ----
/**
 * Business-day date math, backward milestone scheduling from the HubSpot close
 * date, stakeholder resolution from associated contacts, and milestone
 * evaluation (slipped / due soon / next) for the weekly monitor.
 *
 * All dates are calendar dates ("YYYY-MM-DD") computed in UTC, so the result
 * does not depend on the server's timezone.
 */

const DAY_MS = 24 * 3600 * 1000;

function toIsoDate(value) {
  if (value === undefined || value === null || value === '') return null;
  let d;
  if (value instanceof Date) d = value;
  else if (typeof value === 'number' || /^\d{10,13}$/.test(String(value))) {
    const n = Number(value);
    d = new Date(n < 1e12 ? n * 1000 : n);
  } else if (/^\d{4}-\d{2}-\d{2}$/.test(String(value))) d = new Date(`${value}T00:00:00Z`);
  else d = new Date(String(value));
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}

function isoToMs(iso) {
  return Date.parse(`${iso}T00:00:00Z`);
}

function isBusinessDay(iso, holidays = []) {
  const dow = new Date(`${iso}T00:00:00Z`).getUTCDay();
  return dow !== 0 && dow !== 6 && !holidays.includes(iso);
}

/** Moves n business days forward (n > 0) or backward (n < 0). n = 0 returns the date unchanged. */
function addBusinessDays(iso, n, holidays = []) {
  let ms = isoToMs(iso);
  let remaining = Math.abs(n);
  const step = n < 0 ? -DAY_MS : DAY_MS;
  while (remaining > 0) {
    ms += step;
    if (isBusinessDay(new Date(ms).toISOString().slice(0, 10), holidays)) remaining -= 1;
  }
  return new Date(ms).toISOString().slice(0, 10);
}

function rollBackToBusinessDay(iso, holidays = []) {
  let current = iso;
  while (!isBusinessDay(current, holidays)) current = new Date(isoToMs(current) - DAY_MS).toISOString().slice(0, 10);
  return current;
}

/** Business days strictly after `fromIso` up to and including `toIso` (negative when toIso is earlier). */
function businessDaysBetween(fromIso, toIso, holidays = []) {
  if (fromIso === toIso) return 0;
  if (isoToMs(toIso) < isoToMs(fromIso)) return -businessDaysBetween(toIso, fromIso, holidays);
  let count = 0;
  for (let ms = isoToMs(fromIso) + DAY_MS; ms <= isoToMs(toIso); ms += DAY_MS) {
    if (isBusinessDay(new Date(ms).toISOString().slice(0, 10), holidays)) count += 1;
  }
  return count;
}

class PlanError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'PlanError';
    this.code = code;
  }
}

/**
 * Computes target dates. Close-anchored milestones count back from the close date
 * (rolled back to a business day); start-anchored ones count forward from today.
 * When the runway is too short for the template, milestones are spread evenly
 * between start and close (order preserved) and the plan is marked compressed.
 */
function scheduleMilestones({ template, startIso, closeIso, holidays = [], minRunwayBusinessDays = 5 }) {
  if (!closeIso) throw new PlanError('close_date_missing', 'The deal has no close date');
  const closeBd = rollBackToBusinessDay(closeIso, holidays);
  const runway = businessDaysBetween(startIso, closeBd, holidays);
  if (runway < 1) throw new PlanError('close_date_in_past', `Close date ${closeIso} is not after ${startIso}`);
  const raw = template.map((m) => ({
    ...m,
    targetDate: m.anchor === 'start' ? addBusinessDays(startIso, m.offsetBusinessDays, holidays) : addBusinessDays(closeBd, -m.offsetBusinessDays, holidays),
  }));
  const earliest = addBusinessDays(startIso, 1, holidays);
  const outOfBounds = raw.some((m) => m.targetDate < earliest || m.targetDate > closeBd);
  const outOfOrder = raw.some((m, i) => i > 0 && m.targetDate < raw[i - 1].targetDate);
  let compressed = false;
  let milestones = raw;
  if (outOfBounds || outOfOrder) {
    compressed = true;
    milestones = raw.map((m, i) => {
      const position = Math.max(1, Math.round(((i + 1) * runway) / raw.length));
      return { ...m, targetDate: i === raw.length - 1 ? closeBd : addBusinessDays(startIso, Math.min(position, runway), holidays) };
    });
  }
  return {
    startDate: startIso,
    closeDate: closeIso,
    closeBusinessDate: closeBd,
    runwayBusinessDays: runway,
    compressed,
    shortRunway: runway < minRunwayBusinessDays,
    milestones: milestones.map((m) => ({
      key: m.key,
      name: m.name,
      description: m.description || '',
      owner: m.owner,
      internalRole: m.internalRole || 'ae',
      clientRole: m.clientRole || 'champion',
      targetDate: m.targetDate,
    })),
  };
}

const CLIENT_ROLE_RULES = {
  champion: { buying: ['CHAMPION'], title: /\b(?:champion|sponsor|project lead|program manager)\b/i },
  technical: { buying: ['END_USER', 'INFLUENCER'], title: /\b(?:cto|engineer\w*|architect|technical|technology|developer|devops|it\b|data|platform|systems)\b/i },
  security: { buying: [], title: /\b(?:security|ciso|infosec|compliance|risk|privacy)\b/i },
  procurement: { buying: ['LEGAL_AND_COMPLIANCE'], title: /\b(?:procurement|purchasing|legal|counsel|sourcing|vendor management|contracts?)\b/i },
  economic_buyer: { buying: ['BUDGET_HOLDER', 'DECISION_MAKER', 'EXECUTIVE_SPONSOR'], title: /\b(?:cfo|ceo|coo|cro|chief|vp|vice president|president|head of|director|owner|founder)\b/i },
};

function contactDisplayName(c) {
  const name = [c.firstname, c.lastname].filter(Boolean).join(' ').trim();
  return name || 'Unnamed contact';
}

/** Picks one associated contact per client role using hs_buying_role first, then job-title keywords. */
function resolveStakeholders(contacts = []) {
  const people = contacts.map((c) => ({
    id: String(c.id),
    name: contactDisplayName(c),
    jobTitle: c.jobtitle || '',
    email: c.email || '',
    buyingRoles: String(c.hs_buying_role || '').split(';').map((r) => r.trim().toUpperCase()).filter(Boolean),
  }));
  const byRole = {};
  for (const [role, rule] of Object.entries(CLIENT_ROLE_RULES)) {
    const match =
      people.find((p) => p.buyingRoles.some((b) => rule.buying.includes(b))) ||
      people.find((p) => rule.title.test(p.jobTitle)) ||
      null;
    byRole[role] = match;
  }
  if (!byRole.champion) byRole.champion = people[0] || null;
  for (const role of Object.keys(byRole)) if (!byRole[role]) byRole[role] = byRole.champion;
  return { people, byRole };
}

/** Reads per-milestone date/done properties from a deal and classifies each open milestone. */
function evaluateMilestones({ dealProperties, template, todayIso, holidays = [], dueSoonBusinessDays = 3 }) {
  const items = template.map((m) => {
    const targetDate = toIsoDate(dealProperties[`map_${m.key}_date`]);
    const done = String(dealProperties[`map_${m.key}_done`] || '').toLowerCase() === 'true';
    let state = 'scheduled';
    if (done) state = 'done';
    else if (!targetDate) state = 'unscheduled';
    else if (targetDate < todayIso) state = 'slipped';
    else if (businessDaysBetween(todayIso, targetDate, holidays) <= dueSoonBusinessDays) state = 'due_soon';
    const daysLate = state === 'slipped' ? businessDaysBetween(targetDate, todayIso, holidays) : 0;
    return { key: m.key, name: m.name, owner: m.owner, targetDate, done, state, daysLate };
  });
  const open = items.filter((i) => !i.done && i.targetDate).sort((a, b) => a.targetDate.localeCompare(b.targetDate));
  return {
    items,
    slipped: items.filter((i) => i.state === 'slipped'),
    clientSlipped: items.filter((i) => i.state === 'slipped' && (i.owner === 'client' || i.owner === 'both')),
    dueSoon: items.filter((i) => i.state === 'due_soon'),
    next: open[0] || null,
    allDone: items.every((i) => i.done),
  };
}

// ---- src/core/mapDocument.js ----
/**
 * Mutual Action Plan document: a provider-neutral model plus renderers for
 * Markdown (stub / preview), HTML (Google Docs import) and Notion blocks, and
 * the document providers themselves (stub, Google Docs via a service account,
 * Notion API). Every provider honours DRY_RUN and SANDBOX_MODE.
 */

class DocumentSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'DocumentSafetyError';
    this.code = code;
  }
}

function formatHumanDate(iso) {
  if (!iso) return 'TBC';
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' });
}

function formatAmount(amount, currency) {
  const n = Number(amount);
  if (!Number.isFinite(n)) return null;
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency || 'USD', maximumFractionDigits: 0 }).format(n);
  } catch {
    return `${n.toLocaleString('en-US')} ${currency || ''}`.trim();
  }
}

function buildMapModel({ deal, company, owner, plan, stakeholders, config, generatedAt }) {
  const doc = config.document;
  const p = deal.properties || {};
  const companyName = (company && company.name) || p.dealname || 'Customer';
  const ownerName = owner ? [owner.firstName, owner.lastName].filter(Boolean).join(' ') || 'Account Executive' : 'Account Executive';
  const person = (role) => {
    const s = stakeholders.byRole[role];
    if (!s) return 'To be confirmed';
    const base = s.jobTitle ? `${s.name} (${s.jobTitle})` : s.name;
    return doc.includeContactEmails && s.email ? `${base} <${s.email}>` : base;
  };
  const internalPerson = (role) => (role === 'ae' ? ownerName : doc.internalRoleLabels[role] || role);
  return {
    title: `Mutual Action Plan: ${companyName} × ${doc.sellerCompanyName}`,
    dealId: String(deal.id),
    dealName: p.dealname || `Deal ${deal.id}`,
    companyName,
    sellerCompanyName: doc.sellerCompanyName,
    amount: doc.includeAmount ? formatAmount(p.amount, p.deal_currency_code) : null,
    closeDate: plan.closeDate,
    generatedAt,
    compressed: plan.compressed,
    shortRunway: plan.shortRunway,
    stakeholders: stakeholders.people.map((s) => ({
      name: s.name,
      jobTitle: s.jobTitle,
      email: doc.includeContactEmails ? s.email : null,
      roles: Object.entries(stakeholders.byRole)
        .filter(([, v]) => v && v.id === s.id)
        .map(([role]) => role),
    })),
    internalTeam: [{ name: ownerName, role: 'Account Executive' }],
    milestones: plan.milestones.map((m) => ({
      ...m,
      targetDateLabel: formatHumanDate(m.targetDate),
      clientOwner: m.owner === 'internal' ? '—' : person(m.clientRole),
      internalOwner: m.owner === 'client' ? `${internalPerson(m.internalRole)} (support)` : internalPerson(m.internalRole),
      ownerLabel: m.owner === 'both' ? 'Joint' : m.owner === 'client' ? companyName : doc.sellerCompanyName,
    })),
  };
}

function renderMapMarkdown(model) {
  const lines = [
    `# ${model.title}`,
    '',
    `**Deal:** ${model.dealName}  `,
    `**Target close:** ${formatHumanDate(model.closeDate)}  `,
    model.amount ? `**Investment:** ${model.amount}  ` : null,
    `**Plan generated:** ${model.generatedAt.slice(0, 10)}`,
    '',
    model.compressed
      ? '> ⚠️ The timeline is shorter than the standard plan, so milestones were spread evenly up to the close date. Review the dates together at kickoff.'
      : null,
    '',
    '## Purpose',
    '',
    `This plan lists the steps both teams agree to complete for ${model.companyName} to reach a decision by the target close date. Each milestone has one owner on each side. Dates move only by mutual agreement.`,
    '',
    '## Milestones',
    '',
    '| # | Milestone | Target date | Lead | Customer owner | Supplier owner | Status |',
    '| --- | --- | --- | --- | --- | --- | --- |',
    ...model.milestones.map((m, i) => `| ${i + 1} | ${m.name} | ${m.targetDateLabel} | ${m.ownerLabel} | ${m.clientOwner} | ${m.internalOwner} | ☐ Open |`),
    '',
    ...model.milestones.flatMap((m) => [`### ${m.name}: ${m.targetDateLabel}`, '', m.description, '']),
    '## Stakeholders',
    '',
    `**${model.companyName}**`,
    '',
    ...(model.stakeholders.length
      ? model.stakeholders.map((s) => `- ${s.name}${s.jobTitle ? `, ${s.jobTitle}` : ''}${s.roles.length ? ` (${s.roles.map((r) => r.replace('_', ' ')).join(', ')})` : ''}${s.email ? ` · ${s.email}` : ''}`)
      : ['- To be confirmed at kickoff']),
    '',
    `**${model.sellerCompanyName}**`,
    '',
    ...model.internalTeam.map((t) => `- ${t.name}, ${t.role}`),
    '',
    '## How this plan is maintained',
    '',
    '- Completed milestones are ticked off in the CRM, and both teams review this plan weekly.',
    '- If a date is at risk, the owner flags it as early as possible so both teams can agree a new date.',
    '',
  ];
  return lines.filter((l) => l !== null).join('\n');
}

function escapeMapHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function renderMapHtml(model) {
  const rows = model.milestones
    .map((m, i) => `<tr><td>${i + 1}</td><td><b>${escapeMapHtml(m.name)}</b><br>${escapeMapHtml(m.description)}</td><td>${escapeMapHtml(m.targetDateLabel)}</td><td>${escapeMapHtml(m.ownerLabel)}</td><td>${escapeMapHtml(m.clientOwner)}</td><td>${escapeMapHtml(m.internalOwner)}</td><td>☐ Open</td></tr>`)
    .join('');
  const people = model.stakeholders.length
    ? model.stakeholders.map((s) => `<li>${escapeMapHtml(s.name)}${s.jobTitle ? `, ${escapeMapHtml(s.jobTitle)}` : ''}${s.roles.length ? ` (${escapeMapHtml(s.roles.join(', ').replace(/_/g, ' '))})` : ''}${s.email ? ` · ${escapeMapHtml(s.email)}` : ''}</li>`).join('')
    : '<li>To be confirmed at kickoff</li>';
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeMapHtml(model.title)}</title></head><body>
<h1>${escapeMapHtml(model.title)}</h1>
<p><b>Deal:</b> ${escapeMapHtml(model.dealName)}<br><b>Target close:</b> ${escapeMapHtml(formatHumanDate(model.closeDate))}${model.amount ? `<br><b>Investment:</b> ${escapeMapHtml(model.amount)}` : ''}<br><b>Plan generated:</b> ${escapeMapHtml(model.generatedAt.slice(0, 10))}</p>
${model.compressed ? '<p><i>The timeline is shorter than the standard plan, so milestones were spread evenly up to the close date. Review the dates together at kickoff.</i></p>' : ''}
<h2>Purpose</h2><p>This plan lists the steps both teams agree to complete for ${escapeMapHtml(model.companyName)} to reach a decision by the target close date. Each milestone has one owner on each side. Dates move only by mutual agreement.</p>
<h2>Milestones</h2>
<table border="1" cellpadding="6" cellspacing="0"><thead><tr><th>#</th><th>Milestone</th><th>Target date</th><th>Lead</th><th>Customer owner</th><th>Supplier owner</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table>
<h2>Stakeholders</h2><p><b>${escapeMapHtml(model.companyName)}</b></p><ul>${people}</ul>
<p><b>${escapeMapHtml(model.sellerCompanyName)}</b></p><ul>${model.internalTeam.map((t) => `<li>${escapeMapHtml(t.name)}, ${escapeMapHtml(t.role)}</li>`).join('')}</ul>
<h2>How this plan is maintained</h2><ul><li>Completed milestones are ticked off in the CRM, and both teams review this plan weekly.</li><li>If a date is at risk, the owner flags it as early as possible so both teams can agree a new date.</li></ul>
</body></html>`;
}

const notionText = (content) => [{ type: 'text', text: { content: String(content).slice(0, 1900) } }];

function renderMapNotionBlocks(model) {
  const blocks = [
    { object: 'block', type: 'paragraph', paragraph: { rich_text: notionText(`Deal: ${model.dealName} · Target close: ${formatHumanDate(model.closeDate)}${model.amount ? ` · Investment: ${model.amount}` : ''}`) } },
  ];
  if (model.compressed) {
    blocks.push({ object: 'block', type: 'callout', callout: { icon: { type: 'emoji', emoji: '⚠️' }, rich_text: notionText('Short timeline: milestones were spread evenly up to the close date. Review the dates together at kickoff.') } });
  }
  blocks.push({ object: 'block', type: 'heading_2', heading_2: { rich_text: notionText('Milestones') } });
  for (const m of model.milestones) {
    blocks.push({
      object: 'block',
      type: 'to_do',
      to_do: { checked: false, rich_text: notionText(`${m.name}: ${m.targetDateLabel} · Lead: ${m.ownerLabel} · Customer: ${m.clientOwner} · Supplier: ${m.internalOwner}`) },
    });
  }
  blocks.push({ object: 'block', type: 'heading_2', heading_2: { rich_text: notionText('Stakeholders') } });
  for (const s of model.stakeholders.length ? model.stakeholders : [{ name: 'To be confirmed at kickoff', jobTitle: '', roles: [] }]) {
    blocks.push({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: notionText(`${s.name}${s.jobTitle ? `, ${s.jobTitle}` : ''}${s.roles.length ? ` (${s.roles.join(', ').replace(/_/g, ' ')})` : ''}`) } });
  }
  for (const t of model.internalTeam) {
    blocks.push({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: notionText(`${t.name}, ${t.role} (${model.sellerCompanyName})`) } });
  }
  return blocks.slice(0, 100);
}

function base64Url(input) {
  return Buffer.from(input).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
}

/** OAuth 2.0 JWT-bearer flow for a Google service account (no SDK). */
async function getGoogleAccessToken({ serviceAccountJson, scope, fetchImpl, nowMs = Date.now() }) {
  let key;
  try {
    key = typeof serviceAccountJson === 'string' ? JSON.parse(serviceAccountJson) : serviceAccountJson;
  } catch {
    throw new DocumentSafetyError('google_credentials_invalid', 'GOOGLE_SERVICE_ACCOUNT_JSON is not valid JSON');
  }
  if (!key || !key.client_email || !key.private_key) throw new DocumentSafetyError('google_credentials_invalid', 'Service account JSON needs client_email and private_key');
  const iat = Math.floor(nowMs / 1000);
  const header = base64Url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claims = base64Url(JSON.stringify({ iss: key.client_email, scope, aud: 'https://oauth2.googleapis.com/token', iat, exp: iat + 3600 }));
  const signature = crypto.createSign('RSA-SHA256').update(`${header}.${claims}`).sign(key.private_key);
  const assertion = `${header}.${claims}.${base64Url(signature)}`;
  const response = await fetchImpl('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${encodeURIComponent(assertion)}`,
  });
  if (!response.ok) throw new DocumentSafetyError('google_auth_failed', `Google token endpoint returned HTTP ${response.status}`);
  return JSON.parse(await response.text()).access_token;
}

/** Creates the MAP with the configured provider. Returns { provider, mode, url, documentId }. */
async function createMapDocument(model, { config, fetchImpl }) {
  const doc = config.document;
  const dryRunUrl = `${doc.stubBaseUrl.replace(/\/+$/, '')}/deal-${encodeURIComponent(model.dealId)}${config.dryRun ? '?dry_run=true' : ''}`;
  if (doc.provider === 'stub') {
    return { provider: 'stub', mode: config.dryRun ? 'intercepted_dry_run' : 'stub', url: dryRunUrl, documentId: null, markdown: renderMapMarkdown(model) };
  }
  if (config.dryRun) {
    return { provider: doc.provider, mode: 'intercepted_dry_run', url: dryRunUrl, documentId: null, markdown: renderMapMarkdown(model) };
  }
  if (doc.provider === 'google_docs') {
    const folderId = config.sandboxMode ? doc.google.sandboxFolderId : doc.google.folderId;
    if (isPlaceholderSetting(folderId)) throw new DocumentSafetyError('google_folder_missing', 'No Google Drive folder configured for this mode');
    const token = await getGoogleAccessToken({ serviceAccountJson: doc.google.serviceAccountJson, scope: doc.google.scope, fetchImpl });
    const boundary = `map_${crypto.randomBytes(8).toString('hex')}`;
    const metadata = { name: model.title, mimeType: 'application/vnd.google-apps.document', parents: [folderId] };
    const body = [
      `--${boundary}`,
      'Content-Type: application/json; charset=UTF-8',
      '',
      JSON.stringify(metadata),
      `--${boundary}`,
      'Content-Type: text/html; charset=UTF-8',
      '',
      renderMapHtml(model),
      `--${boundary}--`,
      '',
    ].join('\r\n');
    const response = await fetchImpl('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&fields=id,webViewLink', {
      method: 'POST',
      headers: { authorization: `Bearer ${token}`, 'content-type': `multipart/related; boundary=${boundary}` },
      body,
    });
    if (!response.ok) throw new DocumentSafetyError('google_create_failed', `Google Drive returned HTTP ${response.status}`);
    const created = JSON.parse(await response.text());
    return {
      provider: 'google_docs',
      mode: 'created',
      environment: config.sandboxMode ? 'sandbox' : 'production',
      documentId: created.id,
      url: created.webViewLink || `https://docs.google.com/document/d/${created.id}/edit`,
    };
  }
  if (doc.provider === 'notion') {
    const databaseId = config.sandboxMode ? doc.notion.sandboxDatabaseId : doc.notion.databaseId;
    if (isPlaceholderSetting(databaseId)) throw new DocumentSafetyError('notion_database_missing', 'No Notion database configured for this mode');
    const response = await fetchImpl('https://api.notion.com/v1/pages', {
      method: 'POST',
      headers: { authorization: `Bearer ${doc.notion.token}`, 'notion-version': doc.notion.version, 'content-type': 'application/json' },
      body: JSON.stringify({
        parent: { database_id: databaseId },
        properties: { [doc.notion.titleProperty]: { title: notionText(model.title) } },
        children: renderMapNotionBlocks(model),
      }),
    });
    if (!response.ok) throw new DocumentSafetyError('notion_create_failed', `Notion returned HTTP ${response.status}`);
    const created = JSON.parse(await response.text());
    return { provider: 'notion', mode: 'created', environment: config.sandboxMode ? 'sandbox' : 'production', documentId: created.id, url: created.url };
  }
  throw new DocumentSafetyError('provider_invalid', `Unsupported DOC_PROVIDER "${doc.provider}"`);
}

// ---- src/core/hubspot.js ----
/**
 * HubSpot CRM v3/v4 client for the MAP generator.
 *
 * Reads: deal + associated company/contacts + owner, and a paged search for
 * deals with an active MAP. Writes: deal property PATCH only.
 * Safety interlock on every write:
 *   DRY_RUN=true      -> recorded and returned, never sent
 *   SANDBOX_MODE=true -> the token's portal must report a SANDBOX / DEVELOPER_TEST
 *                        account type, or equal HUBSPOT_SANDBOX_PORTAL_ID
 * A placeholder token puts the client offline: reads return synthetic data built
 * from the trigger payload (or injected offline deals), writes are refused.
 */

class HubSpotSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'HubSpotSafetyError';
    this.code = code;
  }
}

class HubSpotRequestError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'HubSpotRequestError';
    this.status = status;
    this.code = `http_${status}`;
  }
}

const MAP_SUMMARY_PROPERTIES = [
  'map_document_url',
  'map_status',
  'map_generated_at',
  'map_next_milestone',
  'map_next_milestone_date',
  'map_slipped_milestones',
  'map_last_nudge_at',
  'map_slack_connect_channel_id',
];
const DEAL_CORE_PROPERTIES = ['dealname', 'amount', 'closedate', 'dealstage', 'pipeline', 'hubspot_owner_id', 'hs_is_closed', 'deal_currency_code'];
const CONTACT_PROPERTIES = ['firstname', 'lastname', 'jobtitle', 'email', 'hs_buying_role'];

function milestonePropertyNames(template) {
  return template.flatMap((m) => [`map_${m.key}_date`, `map_${m.key}_done`]);
}

function dealPropertiesToRead(template) {
  return [...DEAL_CORE_PROPERTIES, ...MAP_SUMMARY_PROPERTIES, ...milestonePropertyNames(template)];
}

function hubspotDealUrl(appBaseUrl, portalId, dealId) {
  if (isPlaceholderSetting(portalId) || !/^\d+$/.test(String(portalId)) || !/^\d+$/.test(String(dealId))) return null;
  return `${String(appBaseUrl).replace(/\/+$/, '')}/contacts/${portalId}/record/0-3/${dealId}`;
}

/** Synthetic bundle for offline simulation: values come from the webhook payload when present. */
function offlineDealBundle(dealId, payload = {}) {
  const props = payload.properties && typeof payload.properties === 'object' ? payload.properties : {};
  const value = (k) => (props[k] && typeof props[k] === 'object' && 'value' in props[k] ? props[k].value : props[k]);
  const offline = payload.offline || {};
  return {
    deal: {
      id: String(dealId),
      properties: {
        dealname: value('dealname') || 'Offline Simulation Deal',
        amount: value('amount') || null,
        closedate: value('closedate') || null,
        dealstage: value('dealstage') || null,
        pipeline: value('pipeline') || 'default',
        hubspot_owner_id: value('hubspot_owner_id') || null,
        hs_is_closed: 'false',
        deal_currency_code: value('deal_currency_code') || 'USD',
        map_document_url: value('map_document_url') || null,
        map_status: value('map_status') || null,
      },
    },
    company: offline.company || { id: 'offline-company', name: 'Example Customer Inc.' },
    contacts: Array.isArray(offline.contacts) ? offline.contacts : [],
    owner: offline.owner || { id: 'offline-owner', firstName: 'Alex', lastName: 'Rivera' },
  };
}

function createMapHubSpotClient({
  token,
  dryRun = true,
  sandboxMode = true,
  sandboxPortalId = '',
  baseUrl = 'https://api.hubapi.com',
  fetchImpl = globalThis.fetch,
  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
  offlineDeals = [],
}) {
  const offline = isPlaceholderSetting(token);
  const apiBase = String(baseUrl).replace(/\/+$/, '');
  const audit = [];
  let sandboxCheck = null;

  async function call(method, path, body, { allow404 = false } = {}) {
    if (offline) throw new HubSpotSafetyError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    for (let attempt = 0; ; attempt += 1) {
      const response = await fetchImpl(`${apiBase}${path}`, {
        method,
        headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      if (response.status === 404 && allow404) return null;
      if ((response.status === 429 || response.status >= 500) && attempt < 3) {
        const retryAfter = Number(response.headers && response.headers.get ? response.headers.get('retry-after') : NaN);
        await sleep(Math.min(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 500 * 2 ** attempt, 10000));
        continue;
      }
      if (!response.ok) throw new HubSpotRequestError(`HubSpot ${method} ${path.split('?')[0]} failed with HTTP ${response.status}`, response.status);
      const text = await response.text();
      return text ? JSON.parse(text) : {};
    }
  }

  async function verifySandbox() {
    if (!sandboxCheck) {
      sandboxCheck = (async () => {
        const details = await call('GET', '/account-info/v3/details');
        const portalId = String(details && details.portalId !== undefined ? details.portalId : '');
        const accountType = String((details && details.accountType) || '').toUpperCase();
        if (!isPlaceholderSetting(sandboxPortalId)) {
          if (portalId !== String(sandboxPortalId)) {
            throw new HubSpotSafetyError('sandbox_portal_mismatch', 'SANDBOX_MODE=true but the token belongs to a portal other than HUBSPOT_SANDBOX_PORTAL_ID');
          }
        } else if (!['SANDBOX', 'DEVELOPER_TEST'].includes(accountType)) {
          throw new HubSpotSafetyError('sandbox_account_required', `SANDBOX_MODE=true but the account type is "${accountType || 'unknown'}"`);
        }
        return { portalId, accountType };
      })();
    }
    return sandboxCheck;
  }

  async function getDealBundle(dealId, { properties, payload } = {}) {
    if (offline) return offlineDealBundle(dealId, payload);
    const deal = await call(
      'GET',
      `/crm/v3/objects/deals/${encodeURIComponent(dealId)}?properties=${encodeURIComponent(properties.join(','))}&associations=companies,contacts`,
      undefined,
      { allow404: true },
    );
    if (!deal) return null;
    const assoc = (type) => ((deal.associations && deal.associations[type] && deal.associations[type].results) || []).map((r) => String(r.id));
    const [companyIds, contactIds] = [assoc('companies'), assoc('contacts')];
    let company = null;
    if (companyIds.length) {
      const companies = await call('POST', '/crm/v3/objects/companies/batch/read', { properties: ['name', 'domain'], inputs: [{ id: companyIds[0] }] });
      const c = companies && companies.results && companies.results[0];
      company = c ? { id: c.id, name: c.properties.name, domain: c.properties.domain } : null;
    }
    let contacts = [];
    if (contactIds.length) {
      const result = await call('POST', '/crm/v3/objects/contacts/batch/read', { properties: CONTACT_PROPERTIES, inputs: contactIds.slice(0, 50).map((id) => ({ id })) });
      contacts = ((result && result.results) || []).map((c) => ({ id: c.id, ...c.properties }));
    }
    let owner = null;
    const ownerId = deal.properties && deal.properties.hubspot_owner_id;
    if (ownerId) {
      const o = await call('GET', `/crm/v3/owners/${encodeURIComponent(ownerId)}`, undefined, { allow404: true });
      owner = o ? { id: String(o.id), firstName: o.firstName || '', lastName: o.lastName || '' } : null;
    }
    return { deal: { id: String(deal.id), properties: deal.properties || {} }, company, contacts, owner };
  }

  async function searchActiveMapDeals({ properties, maxDeals = 500 }) {
    if (offline) return offlineDeals.slice(0, maxDeals);
    const deals = [];
    let after;
    do {
      const body = {
        filterGroups: [{ filters: [{ propertyName: 'map_status', operator: 'EQ', value: 'active' }] }],
        properties,
        limit: 100,
        sorts: [{ propertyName: 'closedate', direction: 'ASCENDING' }],
      };
      if (after) body.after = after;
      const page = await call('POST', '/crm/v3/objects/deals/search', body);
      for (const d of (page && page.results) || []) deals.push({ id: String(d.id), properties: d.properties || {} });
      after = page && page.paging && page.paging.next ? page.paging.next.after : undefined;
    } while (after && deals.length < maxDeals);
    return deals.slice(0, maxDeals);
  }

  async function updateDeal(dealId, properties) {
    if (!properties || !Object.keys(properties).length) return { mode: 'skipped' };
    if (dryRun) {
      const record = { mode: 'intercepted_dry_run', method: 'PATCH', path: `/crm/v3/objects/deals/${dealId}`, properties };
      audit.push(record);
      return record;
    }
    if (sandboxMode) await verifySandbox();
    await call('PATCH', `/crm/v3/objects/deals/${encodeURIComponent(dealId)}`, { properties });
    audit.push({ mode: 'written', method: 'PATCH', path: `/crm/v3/objects/deals/${dealId}` });
    return { mode: 'written', environment: sandboxMode ? 'sandbox' : 'production' };
  }

  return { offline, getDealBundle, searchActiveMapDeals, updateDeal, verifySandbox, auditLog: () => audit.slice() };
}

// ---- src/core/slack.js ----
/**
 * Slack messages (MAP created, internal slip alert, client nudge) and a sender
 * with the same interlocks as the CRM client:
 *   DRY_RUN=true      -> message returned, never sent
 *   SANDBOX_MODE=true -> every message (including client nudges) goes to the
 *                        sandbox channel / webhook only
 * Client nudges go to a Slack Connect channel ID stored on the deal, and only
 * when CLIENT_NUDGES_ENABLED=true.
 */

class SlackSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'SlackSafetyError';
    this.code = code;
  }
}

function slackEscape(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function modeTag(config) {
  if (config.dryRun) return '[DRY RUN] ';
  if (config.sandboxMode) return '[SANDBOX] ';
  return '';
}

function link(url, label) {
  return url && /^https:\/\//.test(url) ? `<${url}|${slackEscape(label)}>` : slackEscape(label);
}

function ownerMention(config, ownerId) {
  const slackId = ownerId ? config.slack.ownerSlackMap[String(ownerId)] : null;
  return slackId && /^[UW][A-Z0-9]{5,}$/.test(slackId) ? `<@${slackId}>` : null;
}

function buildMapCreatedMessage({ model, documentUrl, dealUrl, ownerId, config }) {
  const lines = model.milestones.map((m) => `• *${slackEscape(m.name)}*: ${slackEscape(m.targetDateLabel)} (${slackEscape(m.ownerLabel)})`).join('\n');
  const mention = ownerMention(config, ownerId);
  return {
    kind: 'map_created',
    text: `${modeTag(config)}Mutual Action Plan ready for ${model.dealName}`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: `${modeTag(config)}MAP ready: ${model.dealName}`.slice(0, 150) } },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${mention ? `${mention} ` : ''}${link(documentUrl, 'Open the Mutual Action Plan')} · ${link(dealUrl, 'HubSpot deal')}\nTarget close: *${slackEscape(model.closeDate)}*${model.compressed ? '\n:warning: Short runway: milestones were compressed. Confirm the dates at kickoff.' : ''}`,
        },
      },
      { type: 'section', text: { type: 'mrkdwn', text: lines.slice(0, 2900) } },
    ],
  };
}

function buildSlipAlertMessage({ deal, evaluation, dealUrl, config }) {
  const p = deal.properties;
  const mention = ownerMention(config, p.hubspot_owner_id);
  const fmt = (i) => `• *${slackEscape(i.name)}* (${i.owner === 'internal' ? 'internal' : i.owner === 'both' ? 'joint' : 'client'}): due ${slackEscape(i.targetDate)}, ${i.daysLate} business day${i.daysLate === 1 ? '' : 's'} late`;
  const soon = evaluation.dueSoon.map((i) => `• ${slackEscape(i.name)}: due ${slackEscape(i.targetDate)}`).join('\n');
  return {
    kind: 'slip_alert',
    text: `${modeTag(config)}${evaluation.slipped.length} MAP milestone(s) slipped on ${p.dealname || `deal ${deal.id}`}`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: `${modeTag(config)}MAP slipping: ${p.dealname || `Deal ${deal.id}`}`.slice(0, 150) } },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${mention ? `${mention} ` : ''}${evaluation.slipped.map(fmt).join('\n')}`.slice(0, 2900),
        },
      },
      ...(soon ? [{ type: 'section', text: { type: 'mrkdwn', text: `*Due soon*\n${soon}`.slice(0, 2900) } }] : []),
      {
        type: 'context',
        elements: [{ type: 'mrkdwn', text: `${link(p.map_document_url, 'MAP')} · ${link(dealUrl, 'HubSpot deal')} · close date ${slackEscape(String(p.closedate || '').slice(0, 10) || 'n/a')}` }],
      },
    ],
  };
}

function buildClientNudgeMessage({ deal, evaluation, config }) {
  const p = deal.properties;
  const items = evaluation.clientSlipped.map((i) => `• *${slackEscape(i.name)}* (planned for ${slackEscape(i.targetDate)})`).join('\n');
  return {
    kind: 'client_nudge',
    text: `${modeTag(config)}Quick check-in on the shared plan`,
    blocks: [
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${modeTag(config)}Hi all, a quick check-in on the shared plan. These steps were planned for earlier dates and still show as open:\n${items}\n\nIf any of them is done, or the date needs to move, reply here and I'll update the plan. ${link(p.map_document_url, 'Open the plan')}`.slice(0, 2900),
        },
      },
    ],
  };
}

function validWebhook(url) {
  return !isPlaceholderSetting(url) && String(url).startsWith('https://hooks.slack.com/');
}

function validChannel(id) {
  return !isPlaceholderSetting(id) && /^[CGD][A-Z0-9]{6,}$/.test(String(id));
}

function createMapSlackClient({ config, fetchImpl = globalThis.fetch }) {
  const s = config.slack;
  const hasBot = !isPlaceholderSetting(s.botToken);

  function resolveTarget(channelOverride) {
    if (config.sandboxMode) {
      if (hasBot && validChannel(s.sandboxChannelId)) return { type: 'api', channel: s.sandboxChannelId, environment: 'sandbox' };
      if (validWebhook(s.sandboxWebhookUrl)) return { type: 'webhook', url: s.sandboxWebhookUrl, environment: 'sandbox' };
      throw new SlackSafetyError('slack_sandbox_target_missing', 'SANDBOX_MODE=true requires SLACK_SANDBOX_CHANNEL_ID (with SLACK_BOT_TOKEN) or SLACK_SANDBOX_WEBHOOK_URL');
    }
    if (channelOverride) {
      if (hasBot && validChannel(channelOverride)) return { type: 'api', channel: channelOverride, environment: 'production' };
      return null;
    }
    if (hasBot && validChannel(s.channelId)) return { type: 'api', channel: s.channelId, environment: 'production' };
    if (validWebhook(s.webhookUrl)) return { type: 'webhook', url: s.webhookUrl, environment: 'production' };
    return null;
  }

  async function send(message, { channelOverride = null } = {}) {
    if (config.dryRun) return { mode: 'intercepted_dry_run', kind: message.kind, environment: config.sandboxMode ? 'sandbox' : 'production' };
    const target = resolveTarget(channelOverride);
    if (!target) return { mode: 'not_configured', kind: message.kind };
    const payload = { text: message.text, blocks: message.blocks };
    if (target.type === 'webhook') {
      const response = await fetchImpl(target.url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
      if (!response.ok) throw new Error(`Slack webhook returned HTTP ${response.status}`);
      return { mode: 'sent', kind: message.kind, environment: target.environment, via: 'webhook' };
    }
    const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
      method: 'POST',
      headers: { 'content-type': 'application/json; charset=utf-8', authorization: `Bearer ${s.botToken}` },
      body: JSON.stringify({ channel: target.channel, ...payload, unfurl_links: false }),
    });
    const body = JSON.parse((await response.text()) || '{}');
    if (!response.ok || body.ok !== true) throw new Error(`Slack chat.postMessage failed: ${body.error || response.status}`);
    return { mode: 'sent', kind: message.kind, environment: target.environment, via: 'chat.postMessage' };
  }

  return { send, resolveTarget };
}

