    sellerCompanyName: doc.sellerCompanyName,
    amount: doc.includeAmount ? formatAmount(p.amount, p.deal_currency_code) : null,
    closeDate: plan.closeDate,
    generatedAt,
    compressed: plan.compressed,
    shortRunway: plan.shortRunway,
    stakeholders: stakeholders.people.map((s) => ({
      name: s.name,
      jobTitle: s.jobTitle,
      email: doc.includeContactEmails ? s.email : null,
      roles: Object.entries(stakeholders.byRole)
        .filter(([, v]) => v && v.id === s.id)
        .map(([role]) => role),
    })),
    internalTeam: [{ name: ownerName, role: 'Account Executive' }],
    milestones: plan.milestones.map((m) => ({
      ...m,
      targetDateLabel: formatHumanDate(m.targetDate),
      clientOwner: m.owner === 'internal' ? '—' : person(m.clientRole),
      internalOwner: m.owner === 'client' ? `${internalPerson(m.internalRole)} (support)` : internalPerson(m.internalRole),
      ownerLabel: m.owner === 'both' ? 'Joint' : m.owner === 'client' ? companyName : doc.sellerCompanyName,
    })),
  };
}

function renderMapMarkdown(model) {
  const lines = [
    `# ${model.title}`,
    '',
    `**Deal:** ${model.dealName}  `,
    `**Target close:** ${formatHumanDate(model.closeDate)}  `,
    model.amount ? `**Investment:** ${model.amount}  ` : null,
    `**Plan generated:** ${model.generatedAt.slice(0, 10)}`,
    '',
    model.compressed
      ? '> ⚠️ The timeline is shorter than the standard plan, so milestones were spread evenly up to the close date. Review the dates together at kickoff.'
      : null,
    '',
    '## Purpose',
    '',
    `This plan lists the steps both teams agree to complete for ${model.companyName} to reach a decision by the target close date. Each milestone has one owner on each side. Dates move only by mutual agreement.`,
    '',
    '## Milestones',
    '',
    '| # | Milestone | Target date | Lead | Customer owner | Supplier owner | Status |',
    '| --- | --- | --- | --- | --- | --- | --- |',
    ...model.milestones.map((m, i) => `| ${i + 1} | ${m.name} | ${m.targetDateLabel} | ${m.ownerLabel} | ${m.clientOwner} | ${m.internalOwner} | ☐ Open |`),
    '',
    ...model.milestones.flatMap((m) => [`### ${m.name}: ${m.targetDateLabel}`, '', m.description, '']),
    '## Stakeholders',
    '',
    `**${model.companyName}**`,
    '',
    ...(model.stakeholders.length
      ? model.stakeholders.map((s) => `- ${s.name}${s.jobTitle ? `, ${s.jobTitle}` : ''}${s.roles.length ? ` (${s.roles.map((r) => r.replace('_', ' ')).join(', ')})` : ''}${s.email ? ` · ${s.email}` : ''}`)
      : ['- To be confirmed at kickoff']),
    '',
    `**${model.sellerCompanyName}**`,
    '',
    ...model.internalTeam.map((t) => `- ${t.name}, ${t.role}`),
    '',
    '## How this plan is maintained',
    '',
    '- Completed milestones are ticked off in the CRM, and both teams review this plan weekly.',
    '- If a date is at risk, the owner flags it as early as possible so both teams can agree a new date.',
    '',
  ];
  return lines.filter((l) => l !== null).join('\n');
}

function escapeMapHtml(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function renderMapHtml(model) {
  const rows = model.milestones
    .map((m, i) => `<tr><td>${i + 1}</td><td><b>${escapeMapHtml(m.name)}</b><br>${escapeMapHtml(m.description)}</td><td>${escapeMapHtml(m.targetDateLabel)}</td><td>${escapeMapHtml(m.ownerLabel)}</td><td>${escapeMapHtml(m.clientOwner)}</td><td>${escapeMapHtml(m.internalOwner)}</td><td>☐ Open</td></tr>`)
    .join('');
  const people = model.stakeholders.length
    ? model.stakeholders.map((s) => `<li>${escapeMapHtml(s.name)}${s.jobTitle ? `, ${escapeMapHtml(s.jobTitle)}` : ''}${s.roles.length ? ` (${escapeMapHtml(s.roles.join(', ').replace(/_/g, ' '))})` : ''}${s.email ? ` · ${escapeMapHtml(s.email)}` : ''}</li>`).join('')
    : '<li>To be confirmed at kickoff</li>';
  return `<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeMapHtml(model.title)}</title></head><body>
<h1>${escapeMapHtml(model.title)}</h1>
<p><b>Deal:</b> ${escapeMapHtml(model.dealName)}<br><b>Target close:</b> ${escapeMapHtml(formatHumanDate(model.closeDate))}${model.amount ? `<br><b>Investment:</b> ${escapeMapHtml(model.amount)}` : ''}<br><b>Plan generated:</b> ${escapeMapHtml(model.generatedAt.slice(0, 10))}</p>
${model.compressed ? '<p><i>The timeline is shorter than the standard plan, so milestones were spread evenly up to the close date. Review the dates together at kickoff.</i></p>' : ''}
<h2>Purpose</h2><p>This plan lists the steps both teams agree to complete for ${escapeMapHtml(model.companyName)} to reach a decision by the target close date. Each milestone has one owner on each side. Dates move only by mutual agreement.</p>
<h2>Milestones</h2>
<table border="1" cellpadding="6" cellspacing="0"><thead><tr><th>#</th><th>Milestone</th><th>Target date</th><th>Lead</th><th>Customer owner</th><th>Supplier owner</th><th>Status</th></tr></thead><tbody>${rows}</tbody></table>
<h2>Stakeholders</h2><p><b>${escapeMapHtml(model.companyName)}</b></p><ul>${people}</ul>
<p><b>${escapeMapHtml(model.sellerCompanyName)}</b></p><ul>${model.internalTeam.map((t) => `<li>${escapeMapHtml(t.name)}, ${escapeMapHtml(t.role)}</li>`).join('')}</ul>
<h2>How this plan is maintained</h2><ul><li>Completed milestones are ticked off in the CRM, and both teams review this plan weekly.</li><li>If a date is at risk, the owner flags it as early as possible so both teams can agree a new date.</li></ul>
</body></html>`;
}

const notionText = (content) => [{ type: 'text', text: { content: String(content).slice(0, 1900) } }];

function renderMapNotionBlocks(model) {
  const blocks = [
    { object: 'block', type: 'paragraph', paragraph: { rich_text: notionText(`Deal: ${model.dealName} · Target close: ${formatHumanDate(model.closeDate)}${model.amount ? ` · Investment: ${model.amount}` : ''}`) } },
  ];
  if (model.compressed) {
    blocks.push({ object: 'block', type: 'callout', callout: { icon: { type: 'emoji', emoji: '⚠️' }, rich_text: notionText('Short timeline: milestones were spread evenly up to the close date. Review the dates together at kickoff.') } });
  }
  blocks.push({ object: 'block', type: 'heading_2', heading_2: { rich_text: notionText('Milestones') } });
  for (const m of model.milestones) {
    blocks.push({
      object: 'block',
      type: 'to_do',
      to_do: { checked: false, rich_text: notionText(`${m.name}: ${m.targetDateLabel} · Lead: ${m.ownerLabel} · Customer: ${m.clientOwner} · Supplier: ${m.internalOwner}`) },
    });
  }
  blocks.push({ object: 'block', type: 'heading_2', heading_2: { rich_text: notionText('Stakeholders') } });
  for (const s of model.stakeholders.length ? model.stakeholders : [{ name: 'To be confirmed at kickoff', jobTitle: '', roles: [] }]) {
    blocks.push({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: notionText(`${s.name}${s.jobTitle ? `, ${s.jobTitle}` : ''}${s.roles.length ? ` (${s.roles.join(', ').replace(/_/g, ' ')})` : ''}`) } });
  }
  for (const t of model.internalTeam) {
    blocks.push({ object: 'block', type: 'bulleted_list_item', bulleted_list_item: { rich_text: notionText(`${t.name}, ${t.role} (${model.sellerCompanyName})`) } });
  }
  return blocks.slice(0, 100);
}

function base64Url(input) {
  return Buffer.from(input).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
}

/** OAuth 2.0 JWT-bearer flow for a Google service account (no SDK). */
async function getGoogleAccessToken({ serviceAccountJson, scope, fetchImpl, nowMs = Date.now() }) {
  let key;
  try {
    key = typeof serviceAccountJson === 'string' ? JSON.parse(serviceAccountJson) : serviceAccountJson;
  } catch {
    throw new DocumentSafetyError('google_credentials_invalid', 'GOOGLE_SERVICE_ACCOUNT_JSON is not valid JSON');
  }
  if (!key || !key.client_email || !key.private_key) throw new DocumentSafetyError('google_credentials_invalid', 'Service account JSON needs client_email and private_key');
  const iat = Math.floor(nowMs / 1000);
  const header = base64Url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claims = base64Url(JSON.stringify({ iss: key.client_email, scope, aud: 'https://oauth2.googleapis.com/token', iat, exp: iat + 3600 }));
  const signature = crypto.createSign('RSA-SHA256').update(`${header}.${claims}`).sign(key.private_key);
  const assertion = `${header}.${claims}.${base64Url(signature)}`;
  const response = await fetchImpl('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${encodeURIComponent(assertion)}`,
  });
  if (!response.ok) throw new DocumentSafetyError('google_auth_failed', `Google token endpoint returned HTTP ${response.status}`);
  return JSON.parse(await response.text()).access_token;
}

/** Creates the MAP with the configured provider. Returns { provider, mode, url, documentId }. */
async function createMapDocument(model, { config, fetchImpl }) {
  const doc = config.document;
  const dryRunUrl = `${doc.stubBaseUrl.replace(/\/+$/, '')}/deal-${encodeURIComponent(model.dealId)}${config.dryRun ? '?dry_run=true' : ''}`;
  if (doc.provider === 'stub') {
    return { provider: 'stub', mode: config.dryRun ? 'intercepted_dry_run' : 'stub', url: dryRunUrl, documentId: null, markdown: renderMapMarkdown(model) };
  }
  if (config.dryRun) {
    return { provider: doc.provider, mode: 'intercepted_dry_run', url: dryRunUrl, documentId: null, markdown: renderMapMarkdown(model) };
  }
  if (doc.provider === 'google_docs') {
    const folderId = config.sandboxMode ? doc.google.sandboxFolderId : doc.google.folderId;
    if (isPlaceholderSetting(folderId)) throw new DocumentSafetyError('google_folder_missing', 'No Google Drive folder configured for this mode');
    const token = await getGoogleAccessToken({ serviceAccountJson: doc.google.serviceAccountJson, scope: doc.google.scope, fetchImpl });
    const boundary = `map_${crypto.randomBytes(8).toString('hex')}`;
    const metadata = { name: model.title, mimeType: 'application/vnd.google-apps.document', parents: [folderId] };
    const body = [
      `--${boundary}`,
      'Content-Type: application/json; charset=UTF-8',
      '',
      JSON.stringify(metadata),
      `--${boundary}`,
      'Content-Type: text/html; charset=UTF-8',
      '',
      renderMapHtml(model),
      `--${boundary}--`,
      '',
    ].join('\r\n');
    const response = await fetchImpl('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&fields=id,webViewLink', {
      method: 'POST',
      headers: { authorization: `Bearer ${token}`, 'content-type': `multipart/related; boundary=${boundary}` },
      body,
    });
    if (!response.ok) throw new DocumentSafetyError('google_create_failed', `Google Drive returned HTTP ${response.status}`);
    const created = JSON.parse(await response.text());
    return {
      provider: 'google_docs',
      mode: 'created',
      environment: config.sandboxMode ? 'sandbox' : 'production',
      documentId: created.id,
      url: created.webViewLink || `https://docs.google.com/document/d/${created.id}/edit`,
    };
  }
  if (doc.provider === 'notion') {
    const databaseId = config.sandboxMode ? doc.notion.sandboxDatabaseId : doc.notion.databaseId;
    if (isPlaceholderSetting(databaseId)) throw new DocumentSafetyError('notion_database_missing', 'No Notion database configured for this mode');
    const response = await fetchImpl('https://api.notion.com/v1/pages', {
      method: 'POST',
      headers: { authorization: `Bearer ${doc.notion.token}`, 'notion-version': doc.notion.version, 'content-type': 'application/json' },
      body: JSON.stringify({
        parent: { database_id: databaseId },
        properties: { [doc.notion.titleProperty]: { title: notionText(model.title) } },
        children: renderMapNotionBlocks(model),
      }),
    });
    if (!response.ok) throw new DocumentSafetyError('notion_create_failed', `Notion returned HTTP ${response.status}`);
    const created = JSON.parse(await response.text());
    return { provider: 'notion', mode: 'created', environment: config.sandboxMode ? 'sandbox' : 'production', documentId: created.id, url: created.url };
  }
  throw new DocumentSafetyError('provider_invalid', `Unsupported DOC_PROVIDER "${doc.provider}"`);
}

// ---- src/core/hubspot.js ----
/**
 * HubSpot CRM v3/v4 client for the MAP generator.
 *
 * Reads: deal + associated company/contacts + owner, and a paged search for
 * deals with an active MAP. Writes: deal property PATCH only.
 * Safety interlock on every write:
 *   DRY_RUN=true      -> recorded and returned, never sent
 *   SANDBOX_MODE=true -> the token's portal must report a SANDBOX / DEVELOPER_TEST
 *                        account type, or equal HUBSPOT_SANDBOX_PORTAL_ID
 * A placeholder token puts the client offline: reads return synthetic data built
 * from the trigger payload (or injected offline deals), writes are refused.
 */

class HubSpotSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'HubSpotSafetyError';
    this.code = code;
  }
}

class HubSpotRequestError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'HubSpotRequestError';
    this.status = status;
    this.code = `http_${status}`;
  }
}

const MAP_SUMMARY_PROPERTIES = [
  'map_document_url',
  'map_status',
  'map_generated_at',
  'map_next_milestone',
  'map_next_milestone_date',
  'map_slipped_milestones',
  'map_last_nudge_at',
  'map_slack_connect_channel_id',
];
const DEAL_CORE_PROPERTIES = ['dealname', 'amount', 'closedate', 'dealstage', 'pipeline', 'hubspot_owner_id', 'hs_is_closed', 'deal_currency_code'];
const CONTACT_PROPERTIES = ['firstname', 'lastname', 'jobtitle', 'email', 'hs_buying_role'];

function milestonePropertyNames(template) {
  return template.flatMap((m) => [`map_${m.key}_date`, `map_${m.key}_done`]);
}

function dealPropertiesToRead(template) {
  return [...DEAL_CORE_PROPERTIES, ...MAP_SUMMARY_PROPERTIES, ...milestonePropertyNames(template)];
}

function hubspotDealUrl(appBaseUrl, portalId, dealId) {
  if (isPlaceholderSetting(portalId) || !/^\d+$/.test(String(portalId)) || !/^\d+$/.test(String(dealId))) return null;
  return `${String(appBaseUrl).replace(/\/+$/, '')}/contacts/${portalId}/record/0-3/${dealId}`;
}

/** Synthetic bundle for offline simulation: values come from the webhook payload when present. */
function offlineDealBundle(dealId, payload = {}) {
  const props = payload.properties && typeof payload.properties === 'object' ? payload.properties : {};
  const value = (k) => (props[k] && typeof props[k] === 'object' && 'value' in props[k] ? props[k].value : props[k]);
  const offline = payload.offline || {};
  return {
    deal: {
      id: String(dealId),
      properties: {
        dealname: value('dealname') || 'Offline Simulation Deal',
        amount: value('amount') || null,
        closedate: value('closedate') || null,
        dealstage: value('dealstage') || null,
        pipeline: value('pipeline') || 'default',
        hubspot_owner_id: value('hubspot_owner_id') || null,
        hs_is_closed: 'false',
        deal_currency_code: value('deal_currency_code') || 'USD',
        map_document_url: value('map_document_url') || null,
        map_status: value('map_status') || null,
      },
    },
    company: offline.company || { id: 'offline-company', name: 'Example Customer Inc.' },
    contacts: Array.isArray(offline.contacts) ? offline.contacts : [],
    owner: offline.owner || { id: 'offline-owner', firstName: 'Alex', lastName: 'Rivera' },
  };
}

function createMapHubSpotClient({
  token,
  dryRun = true,
  sandboxMode = true,
  sandboxPortalId = '',
  baseUrl = 'https://api.hubapi.com',
  fetchImpl = globalThis.fetch,
  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
  offlineDeals = [],
}) {
  const offline = isPlaceholderSetting(token);
  const apiBase = String(baseUrl).replace(/\/+$/, '');
  const audit = [];
  let sandboxCheck = null;

  async function call(method, path, body, { allow404 = false } = {}) {
    if (offline) throw new HubSpotSafetyError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    for (let attempt = 0; ; attempt += 1) {
      const response = await fetchImpl(`${apiBase}${path}`, {
        method,
        headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      if (response.status === 404 && allow404) return null;
      if ((response.status === 429 || response.status >= 500) && attempt < 3) {
        const retryAfter = Number(response.headers && response.headers.get ? response.headers.get('retry-after') : NaN);
        await sleep(Math.min(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 500 * 2 ** attempt, 10000));
        continue;
      }
      if (!response.ok) throw new HubSpotRequestError(`HubSpot ${method} ${path.split('?')[0]} failed with HTTP ${response.status}`, response.status);
      const text = await response.text();
      return text ? JSON.parse(text) : {};
    }
  }

  async function verifySandbox() {
    if (!sandboxCheck) {
      sandboxCheck = (async () => {
        const details = await call('GET', '/account-info/v3/details');
        const portalId = String(details && details.portalId !== undefined ? details.portalId : '');
        const accountType = String((details && details.accountType) || '').toUpperCase();
        if (!isPlaceholderSetting(sandboxPortalId)) {
          if (portalId !== String(sandboxPortalId)) {
            throw new HubSpotSafetyError('sandbox_portal_mismatch', 'SANDBOX_MODE=true but the token belongs to a portal other than HUBSPOT_SANDBOX_PORTAL_ID');
          }
        } else if (!['SANDBOX', 'DEVELOPER_TEST'].includes(accountType)) {
          throw new HubSpotSafetyError('sandbox_account_required', `SANDBOX_MODE=true but the account type is "${accountType || 'unknown'}"`);
        }
        return { portalId, accountType };
      })();
    }
    return sandboxCheck;
  }

  async function getDealBundle(dealId, { properties, payload } = {}) {
    if (offline) return offlineDealBundle(dealId, payload);
    const deal = await call(
      'GET',
      `/crm/v3/objects/deals/${encodeURIComponent(dealId)}?properties=${encodeURIComponent(properties.join(','))}&associations=companies,contacts`,
      undefined,
      { allow404: true },
    );
    if (!deal) return null;
    const assoc = (type) => ((deal.associations && deal.associations[type] && deal.associations[type].results) || []).map((r) => String(r.id));
    const [companyIds, contactIds] = [assoc('companies'), assoc('contacts')];
    let company = null;
    if (companyIds.length) {
      const companies = await call('POST', '/crm/v3/objects/companies/batch/read', { properties: ['name', 'domain'], inputs: [{ id: companyIds[0] }] });
      const c = companies && companies.results && companies.results[0];
      company = c ? { id: c.id, name: c.properties.name, domain: c.properties.domain } : null;
    }
    let contacts = [];
    if (contactIds.length) {
      const result = await call('POST', '/crm/v3/objects/contacts/batch/read', { properties: CONTACT_PROPERTIES, inputs: contactIds.slice(0, 50).map((id) => ({ id })) });
      contacts = ((result && result.results) || []).map((c) => ({ id: c.id, ...c.properties }));
    }
    let owner = null;
    const ownerId = deal.properties && deal.properties.hubspot_owner_id;
    if (ownerId) {
      const o = await call('GET', `/crm/v3/owners/${encodeURIComponent(ownerId)}`, undefined, { allow404: true });
      owner = o ? { id: String(o.id), firstName: o.firstName || '', lastName: o.lastName || '' } : null;
    }
    return { deal: { id: String(deal.id), properties: deal.properties || {} }, company, contacts, owner };
  }

  async function searchActiveMapDeals({ properties, maxDeals = 500 }) {
    if (offline) return offlineDeals.slice(0, maxDeals);
    const deals = [];
    let after;
    do {
      const body = {
        filterGroups: [{ filters: [{ propertyName: 'map_status', operator: 'EQ', value: 'active' }] }],
        properties,
        limit: 100,
        sorts: [{ propertyName: 'closedate', direction: 'ASCENDING' }],
      };
      if (after) body.after = after;
      const page = await call('POST', '/crm/v3/objects/deals/search', body);
      for (const d of (page && page.results) || []) deals.push({ id: String(d.id), properties: d.properties || {} });
      after = page && page.paging && page.paging.next ? page.paging.next.after : undefined;
    } while (after && deals.length < maxDeals);
    return deals.slice(0, maxDeals);
  }

  async function updateDeal(dealId, properties) {
    if (!properties || !Object.keys(properties).length) return { mode: 'skipped' };
    if (dryRun) {
      const record = { mode: 'intercepted_dry_run', method: 'PATCH', path: `/crm/v3/objects/deals/${dealId}`, properties };
      audit.push(record);
      return record;
    }
    if (sandboxMode) await verifySandbox();
    await call('PATCH', `/crm/v3/objects/deals/${encodeURIComponent(dealId)}`, { properties });
    audit.push({ mode: 'written', method: 'PATCH', path: `/crm/v3/objects/deals/${dealId}` });
    return { mode: 'written', environment: sandboxMode ? 'sandbox' : 'production' };
  }

  return { offline, getDealBundle, searchActiveMapDeals, updateDeal, verifySandbox, auditLog: () => audit.slice() };
}

// ---- src/core/slack.js ----
/**
 * Slack messages (MAP created, internal slip alert, client nudge) and a sender
 * with the same interlocks as the CRM client:
 *   DRY_RUN=true      -> message returned, never sent
 *   SANDBOX_MODE=true -> every message (including client nudges) goes to the
 *                        sandbox channel / webhook only
 * Client nudges go to a Slack Connect channel ID stored on the deal, and only
 * when CLIENT_NUDGES_ENABLED=true.
 */

class SlackSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'SlackSafetyError';
    this.code = code;
  }
}

function slackEscape(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function modeTag(config) {
  if (config.dryRun) return '[DRY RUN] ';
  if (config.sandboxMode) return '[SANDBOX] ';
  return '';
}

function link(url, label) {
  return url && /^https:\/\//.test(url) ? `<${url}|${slackEscape(label)}>` : slackEscape(label);
}

function ownerMention(config, ownerId) {
  const slackId = ownerId ? config.slack.ownerSlackMap[String(ownerId)] : null;
  return slackId && /^[UW][A-Z0-9]{5,}$/.test(slackId) ? `<@${slackId}>` : null;
}

function buildMapCreatedMessage({ model, documentUrl, dealUrl, ownerId, config }) {
  const lines = model.milestones.map((m) => `• *${slackEscape(m.name)}*: ${slackEscape(m.targetDateLabel)} (${slackEscape(m.ownerLabel)})`).join('\n');
  const mention = ownerMention(config, ownerId);
  return {
    kind: 'map_created',
    text: `${modeTag(config)}Mutual Action Plan ready for ${model.dealName}`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: `${modeTag(config)}MAP ready: ${model.dealName}`.slice(0, 150) } },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${mention ? `${mention} ` : ''}${link(documentUrl, 'Open the Mutual Action Plan')} · ${link(dealUrl, 'HubSpot deal')}\nTarget close: *${slackEscape(model.closeDate)}*${model.compressed ? '\n:warning: Short runway: milestones were compressed. Confirm the dates at kickoff.' : ''}`,
        },
      },
      { type: 'section', text: { type: 'mrkdwn', text: lines.slice(0, 2900) } },
    ],
  };
}

function buildSlipAlertMessage({ deal, evaluation, dealUrl, config }) {
  const p = deal.properties;
  const mention = ownerMention(config, p.hubspot_owner_id);
  const fmt = (i) => `• *${slackEscape(i.name)}* (${i.owner === 'internal' ? 'internal' : i.owner === 'both' ? 'joint' : 'client'}): due ${slackEscape(i.targetDate)}, ${i.daysLate} business day${i.daysLate === 1 ? '' : 's'} late`;
  const soon = evaluation.dueSoon.map((i) => `• ${slackEscape(i.name)}: due ${slackEscape(i.targetDate)}`).join('\n');
  return {
    kind: 'slip_alert',
