function validateMapConfig(config) {
  const errors = [];
  const warnings = [];
  const live = !config.dryRun;
  if (config.schedule.template && config.schedule.template.__invalidJson) errors.push('MILESTONE_TEMPLATE_JSON is not valid JSON');
  else errors.push(...validateMilestoneTemplate(config.schedule.template));
  if (config.document.provider === 'invalid') errors.push('DOC_PROVIDER must be stub, google_docs or notion');
  for (const h of config.schedule.holidays) if (!/^\d{4}-\d{2}-\d{2}$/.test(h)) errors.push(`HOLIDAYS entry "${h}" must be YYYY-MM-DD`);
  if (!config.trigger.stageIds.length) errors.push('TRIGGER_STAGE_IDS must list at least one deal stage ID');
  if (isPlaceholderSetting(config.webhook.secret)) {
    if (live) errors.push('N8N_WEBHOOK_SECRET is missing or a placeholder');
    else warnings.push('N8N_WEBHOOK_SECRET is a placeholder: webhook authentication is skipped in dry run');
  }
  if (live) {
    if (isPlaceholderSetting(config.hubspot.token)) errors.push('HUBSPOT_PRIVATE_APP_TOKEN is missing or a placeholder');
    if (config.document.provider === 'stub') warnings.push('DOC_PROVIDER=stub: deals receive a placeholder MAP URL');
    if (config.document.provider === 'google_docs') {
      if (isPlaceholderSetting(config.document.google.serviceAccountJson)) errors.push('GOOGLE_SERVICE_ACCOUNT_JSON is required for DOC_PROVIDER=google_docs');
      const folder = config.sandboxMode ? config.document.google.sandboxFolderId : config.document.google.folderId;
      if (isPlaceholderSetting(folder)) errors.push(config.sandboxMode ? 'GOOGLE_SANDBOX_FOLDER_ID is required in SANDBOX_MODE' : 'GOOGLE_DRIVE_FOLDER_ID is required');
    }
    if (config.document.provider === 'notion') {
      if (isPlaceholderSetting(config.document.notion.token)) errors.push('NOTION_API_TOKEN is required for DOC_PROVIDER=notion');
      const db = config.sandboxMode ? config.document.notion.sandboxDatabaseId : config.document.notion.databaseId;
      if (isPlaceholderSetting(db)) errors.push(config.sandboxMode ? 'NOTION_SANDBOX_DATABASE_ID is required in SANDBOX_MODE' : 'NOTION_DATABASE_ID is required');
    }
    if (!config.sandboxMode) warnings.push('SANDBOX_MODE=false and DRY_RUN=false: production HubSpot, documents and Slack are modified');
  }
  return { errors, warnings };
}

// ---- src/core/milestones.js ----
/**
 * Business-day date math, backward milestone scheduling from the HubSpot close
 * date, stakeholder resolution from associated contacts, and milestone
 * evaluation (slipped / due soon / next) for the weekly monitor.
 *
 * All dates are calendar dates ("YYYY-MM-DD") computed in UTC, so the result
 * does not depend on the server's timezone.
 */

const DAY_MS = 24 * 3600 * 1000;

function toIsoDate(value) {
  if (value === undefined || value === null || value === '') return null;
  let d;
  if (value instanceof Date) d = value;
  else if (typeof value === 'number' || /^\d{10,13}$/.test(String(value))) {
    const n = Number(value);
    d = new Date(n < 1e12 ? n * 1000 : n);
  } else if (/^\d{4}-\d{2}-\d{2}$/.test(String(value))) d = new Date(`${value}T00:00:00Z`);
  else d = new Date(String(value));
  return Number.isNaN(d.getTime()) ? null : d.toISOString().slice(0, 10);
}

function isoToMs(iso) {
  return Date.parse(`${iso}T00:00:00Z`);
}

function isBusinessDay(iso, holidays = []) {
  const dow = new Date(`${iso}T00:00:00Z`).getUTCDay();
  return dow !== 0 && dow !== 6 && !holidays.includes(iso);
}

/** Moves n business days forward (n > 0) or backward (n < 0). n = 0 returns the date unchanged. */
function addBusinessDays(iso, n, holidays = []) {
  let ms = isoToMs(iso);
  let remaining = Math.abs(n);
  const step = n < 0 ? -DAY_MS : DAY_MS;
  while (remaining > 0) {
    ms += step;
    if (isBusinessDay(new Date(ms).toISOString().slice(0, 10), holidays)) remaining -= 1;
  }
  return new Date(ms).toISOString().slice(0, 10);
}

function rollBackToBusinessDay(iso, holidays = []) {
  let current = iso;
  while (!isBusinessDay(current, holidays)) current = new Date(isoToMs(current) - DAY_MS).toISOString().slice(0, 10);
  return current;
}

/** Business days strictly after `fromIso` up to and including `toIso` (negative when toIso is earlier). */
function businessDaysBetween(fromIso, toIso, holidays = []) {
  if (fromIso === toIso) return 0;
  if (isoToMs(toIso) < isoToMs(fromIso)) return -businessDaysBetween(toIso, fromIso, holidays);
  let count = 0;
  for (let ms = isoToMs(fromIso) + DAY_MS; ms <= isoToMs(toIso); ms += DAY_MS) {
    if (isBusinessDay(new Date(ms).toISOString().slice(0, 10), holidays)) count += 1;
  }
  return count;
}

class PlanError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'PlanError';
    this.code = code;
  }
}

/**
 * Computes target dates. Close-anchored milestones count back from the close date
 * (rolled back to a business day); start-anchored ones count forward from today.
 * When the runway is too short for the template, milestones are spread evenly
 * between start and close (order preserved) and the plan is marked compressed.
 */
function scheduleMilestones({ template, startIso, closeIso, holidays = [], minRunwayBusinessDays = 5 }) {
  if (!closeIso) throw new PlanError('close_date_missing', 'The deal has no close date');
  const closeBd = rollBackToBusinessDay(closeIso, holidays);
  const runway = businessDaysBetween(startIso, closeBd, holidays);
  if (runway < 1) throw new PlanError('close_date_in_past', `Close date ${closeIso} is not after ${startIso}`);
  const raw = template.map((m) => ({
    ...m,
    targetDate: m.anchor === 'start' ? addBusinessDays(startIso, m.offsetBusinessDays, holidays) : addBusinessDays(closeBd, -m.offsetBusinessDays, holidays),
  }));
  const earliest = addBusinessDays(startIso, 1, holidays);
  const outOfBounds = raw.some((m) => m.targetDate < earliest || m.targetDate > closeBd);
  const outOfOrder = raw.some((m, i) => i > 0 && m.targetDate < raw[i - 1].targetDate);
  let compressed = false;
  let milestones = raw;
  if (outOfBounds || outOfOrder) {
    compressed = true;
    milestones = raw.map((m, i) => {
      const position = Math.max(1, Math.round(((i + 1) * runway) / raw.length));
      return { ...m, targetDate: i === raw.length - 1 ? closeBd : addBusinessDays(startIso, Math.min(position, runway), holidays) };
    });
  }
  return {
    startDate: startIso,
    closeDate: closeIso,
    closeBusinessDate: closeBd,
    runwayBusinessDays: runway,
    compressed,
    shortRunway: runway < minRunwayBusinessDays,
    milestones: milestones.map((m) => ({
      key: m.key,
      name: m.name,
      description: m.description || '',
      owner: m.owner,
      internalRole: m.internalRole || 'ae',
      clientRole: m.clientRole || 'champion',
      targetDate: m.targetDate,
    })),
  };
}

const CLIENT_ROLE_RULES = {
  champion: { buying: ['CHAMPION'], title: /\b(?:champion|sponsor|project lead|program manager)\b/i },
  technical: { buying: ['END_USER', 'INFLUENCER'], title: /\b(?:cto|engineer\w*|architect|technical|technology|developer|devops|it\b|data|platform|systems)\b/i },
  security: { buying: [], title: /\b(?:security|ciso|infosec|compliance|risk|privacy)\b/i },
  procurement: { buying: ['LEGAL_AND_COMPLIANCE'], title: /\b(?:procurement|purchasing|legal|counsel|sourcing|vendor management|contracts?)\b/i },
  economic_buyer: { buying: ['BUDGET_HOLDER', 'DECISION_MAKER', 'EXECUTIVE_SPONSOR'], title: /\b(?:cfo|ceo|coo|cro|chief|vp|vice president|president|head of|director|owner|founder)\b/i },
};

function contactDisplayName(c) {
  const name = [c.firstname, c.lastname].filter(Boolean).join(' ').trim();
  return name || 'Unnamed contact';
}

/** Picks one associated contact per client role using hs_buying_role first, then job-title keywords. */
function resolveStakeholders(contacts = []) {
  const people = contacts.map((c) => ({
    id: String(c.id),
    name: contactDisplayName(c),
    jobTitle: c.jobtitle || '',
    email: c.email || '',
    buyingRoles: String(c.hs_buying_role || '').split(';').map((r) => r.trim().toUpperCase()).filter(Boolean),
  }));
  const byRole = {};
  for (const [role, rule] of Object.entries(CLIENT_ROLE_RULES)) {
    const match =
      people.find((p) => p.buyingRoles.some((b) => rule.buying.includes(b))) ||
      people.find((p) => rule.title.test(p.jobTitle)) ||
      null;
    byRole[role] = match;
  }
  if (!byRole.champion) byRole.champion = people[0] || null;
  for (const role of Object.keys(byRole)) if (!byRole[role]) byRole[role] = byRole.champion;
  return { people, byRole };
}

/** Reads per-milestone date/done properties from a deal and classifies each open milestone. */
function evaluateMilestones({ dealProperties, template, todayIso, holidays = [], dueSoonBusinessDays = 3 }) {
  const items = template.map((m) => {
    const targetDate = toIsoDate(dealProperties[`map_${m.key}_date`]);
    const done = String(dealProperties[`map_${m.key}_done`] || '').toLowerCase() === 'true';
    let state = 'scheduled';
    if (done) state = 'done';
    else if (!targetDate) state = 'unscheduled';
    else if (targetDate < todayIso) state = 'slipped';
    else if (businessDaysBetween(todayIso, targetDate, holidays) <= dueSoonBusinessDays) state = 'due_soon';
    const daysLate = state === 'slipped' ? businessDaysBetween(targetDate, todayIso, holidays) : 0;
    return { key: m.key, name: m.name, owner: m.owner, targetDate, done, state, daysLate };
  });
  const open = items.filter((i) => !i.done && i.targetDate).sort((a, b) => a.targetDate.localeCompare(b.targetDate));
  return {
    items,
    slipped: items.filter((i) => i.state === 'slipped'),
    clientSlipped: items.filter((i) => i.state === 'slipped' && (i.owner === 'client' || i.owner === 'both')),
    dueSoon: items.filter((i) => i.state === 'due_soon'),
    next: open[0] || null,
    allDone: items.every((i) => i.done),
  };
}

// ---- src/core/mapDocument.js ----
/**
 * Mutual Action Plan document: a provider-neutral model plus renderers for
 * Markdown (stub / preview), HTML (Google Docs import) and Notion blocks, and
 * the document providers themselves (stub, Google Docs via a service account,
 * Notion API). Every provider honours DRY_RUN and SANDBOX_MODE.
 */

class DocumentSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'DocumentSafetyError';
    this.code = code;
  }
}

function formatHumanDate(iso) {
  if (!iso) return 'TBC';
  return new Date(`${iso}T00:00:00Z`).toLocaleDateString('en-US', { weekday: 'short', year: 'numeric', month: 'short', day: 'numeric', timeZone: 'UTC' });
}

function formatAmount(amount, currency) {
  const n = Number(amount);
  if (!Number.isFinite(n)) return null;
  try {
    return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency || 'USD', maximumFractionDigits: 0 }).format(n);
  } catch {
    return `${n.toLocaleString('en-US')} ${currency || ''}`.trim();
  }
}

function buildMapModel({ deal, company, owner, plan, stakeholders, config, generatedAt }) {
  const doc = config.document;
  const p = deal.properties || {};
  const companyName = (company && company.name) || p.dealname || 'Customer';
  const ownerName = owner ? [owner.firstName, owner.lastName].filter(Boolean).join(' ') || 'Account Executive' : 'Account Executive';
  const person = (role) => {
    const s = stakeholders.byRole[role];
    if (!s) return 'To be confirmed';
    const base = s.jobTitle ? `${s.name} (${s.jobTitle})` : s.name;
    return doc.includeContactEmails && s.email ? `${base} <${s.email}>` : base;
  };
  const internalPerson = (role) => (role === 'ae' ? ownerName : doc.internalRoleLabels[role] || role);
  return {
    title: `Mutual Action Plan: ${companyName} × ${doc.sellerCompanyName}`,
    dealId: String(deal.id),
    dealName: p.dealname || `Deal ${deal.id}`,
    companyName,
    sellerCompanyName: doc.sellerCompanyName,
    amount: doc.includeAmount ? formatAmount(p.amount, p.deal_currency_code) : null,
    closeDate: plan.closeDate,
    generatedAt,
    compressed: plan.compressed,
    shortRunway: plan.shortRunway,
    stakeholders: stakeholders.people.map((s) => ({
      name: s.name,
      jobTitle: s.jobTitle,
      email: doc.includeContactEmails ? s.email : null,
      roles: Object.entries(stakeholders.byRole)
        .filter(([, v]) => v && v.id === s.id)
        .map(([role]) => role),
    })),
    internalTeam: [{ name: ownerName, role: 'Account Executive' }],
    milestones: plan.milestones.map((m) => ({
      ...m,
      targetDateLabel: formatHumanDate(m.targetDate),
      clientOwner: m.owner === 'internal' ? '—' : person(m.clientRole),
      internalOwner: m.owner === 'client' ? `${internalPerson(m.internalRole)} (support)` : internalPerson(m.internalRole),
      ownerLabel: m.owner === 'both' ? 'Joint' : m.owner === 'client' ? companyName : doc.sellerCompanyName,
    })),
  };
}

function renderMapMarkdown(model) {
