  }
  return blocks.slice(0, 100);
}

function base64Url(input) {
  return Buffer.from(input).toString('base64').replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
}

/** OAuth 2.0 JWT-bearer flow for a Google service account (no SDK). */
async function getGoogleAccessToken({ serviceAccountJson, scope, fetchImpl, nowMs = Date.now() }) {
  let key;
  try {
    key = typeof serviceAccountJson === 'string' ? JSON.parse(serviceAccountJson) : serviceAccountJson;
  } catch {
    throw new DocumentSafetyError('google_credentials_invalid', 'GOOGLE_SERVICE_ACCOUNT_JSON is not valid JSON');
  }
  if (!key || !key.client_email || !key.private_key) throw new DocumentSafetyError('google_credentials_invalid', 'Service account JSON needs client_email and private_key');
  const iat = Math.floor(nowMs / 1000);
  const header = base64Url(JSON.stringify({ alg: 'RS256', typ: 'JWT' }));
  const claims = base64Url(JSON.stringify({ iss: key.client_email, scope, aud: 'https://oauth2.googleapis.com/token', iat, exp: iat + 3600 }));
  const signature = crypto.createSign('RSA-SHA256').update(`${header}.${claims}`).sign(key.private_key);
  const assertion = `${header}.${claims}.${base64Url(signature)}`;
  const response = await fetchImpl('https://oauth2.googleapis.com/token', {
    method: 'POST',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: `grant_type=${encodeURIComponent('urn:ietf:params:oauth:grant-type:jwt-bearer')}&assertion=${encodeURIComponent(assertion)}`,
  });
  if (!response.ok) throw new DocumentSafetyError('google_auth_failed', `Google token endpoint returned HTTP ${response.status}`);
  return JSON.parse(await response.text()).access_token;
}

/** Creates the MAP with the configured provider. Returns { provider, mode, url, documentId }. */
async function createMapDocument(model, { config, fetchImpl }) {
  const doc = config.document;
  const dryRunUrl = `${doc.stubBaseUrl.replace(/\/+$/, '')}/deal-${encodeURIComponent(model.dealId)}${config.dryRun ? '?dry_run=true' : ''}`;
  if (doc.provider === 'stub') {
    return { provider: 'stub', mode: config.dryRun ? 'intercepted_dry_run' : 'stub', url: dryRunUrl, documentId: null, markdown: renderMapMarkdown(model) };
  }
  if (config.dryRun) {
    return { provider: doc.provider, mode: 'intercepted_dry_run', url: dryRunUrl, documentId: null, markdown: renderMapMarkdown(model) };
  }
  if (doc.provider === 'google_docs') {
    const folderId = config.sandboxMode ? doc.google.sandboxFolderId : doc.google.folderId;
    if (isPlaceholderSetting(folderId)) throw new DocumentSafetyError('google_folder_missing', 'No Google Drive folder configured for this mode');
    const token = await getGoogleAccessToken({ serviceAccountJson: doc.google.serviceAccountJson, scope: doc.google.scope, fetchImpl });
    const boundary = `map_${crypto.randomBytes(8).toString('hex')}`;
    const metadata = { name: model.title, mimeType: 'application/vnd.google-apps.document', parents: [folderId] };
    const body = [
      `--${boundary}`,
      'Content-Type: application/json; charset=UTF-8',
      '',
      JSON.stringify(metadata),
      `--${boundary}`,
      'Content-Type: text/html; charset=UTF-8',
      '',
      renderMapHtml(model),
      `--${boundary}--`,
      '',
    ].join('\r\n');
    const response = await fetchImpl('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&supportsAllDrives=true&fields=id,webViewLink', {
      method: 'POST',
      headers: { authorization: `Bearer ${token}`, 'content-type': `multipart/related; boundary=${boundary}` },
      body,
    });
    if (!response.ok) throw new DocumentSafetyError('google_create_failed', `Google Drive returned HTTP ${response.status}`);
    const created = JSON.parse(await response.text());
    return {
      provider: 'google_docs',
      mode: 'created',
      environment: config.sandboxMode ? 'sandbox' : 'production',
      documentId: created.id,
      url: created.webViewLink || `https://docs.google.com/document/d/${created.id}/edit`,
    };
  }
  if (doc.provider === 'notion') {
    const databaseId = config.sandboxMode ? doc.notion.sandboxDatabaseId : doc.notion.databaseId;
    if (isPlaceholderSetting(databaseId)) throw new DocumentSafetyError('notion_database_missing', 'No Notion database configured for this mode');
    const response = await fetchImpl('https://api.notion.com/v1/pages', {
      method: 'POST',
      headers: { authorization: `Bearer ${doc.notion.token}`, 'notion-version': doc.notion.version, 'content-type': 'application/json' },
      body: JSON.stringify({
        parent: { database_id: databaseId },
        properties: { [doc.notion.titleProperty]: { title: notionText(model.title) } },
        children: renderMapNotionBlocks(model),
      }),
    });
    if (!response.ok) throw new DocumentSafetyError('notion_create_failed', `Notion returned HTTP ${response.status}`);
    const created = JSON.parse(await response.text());
    return { provider: 'notion', mode: 'created', environment: config.sandboxMode ? 'sandbox' : 'production', documentId: created.id, url: created.url };
  }
  throw new DocumentSafetyError('provider_invalid', `Unsupported DOC_PROVIDER "${doc.provider}"`);
}

// ---- src/core/hubspot.js ----
/**
 * HubSpot CRM v3/v4 client for the MAP generator.
 *
 * Reads: deal + associated company/contacts + owner, and a paged search for
 * deals with an active MAP. Writes: deal property PATCH only.
 * Safety interlock on every write:
 *   DRY_RUN=true      -> recorded and returned, never sent
 *   SANDBOX_MODE=true -> the token's portal must report a SANDBOX / DEVELOPER_TEST
 *                        account type, or equal HUBSPOT_SANDBOX_PORTAL_ID
 * A placeholder token puts the client offline: reads return synthetic data built
 * from the trigger payload (or injected offline deals), writes are refused.
 */

class HubSpotSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'HubSpotSafetyError';
    this.code = code;
  }
}

class HubSpotRequestError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'HubSpotRequestError';
    this.status = status;
    this.code = `http_${status}`;
  }
}

const MAP_SUMMARY_PROPERTIES = [
  'map_document_url',
  'map_status',
  'map_generated_at',
  'map_next_milestone',
  'map_next_milestone_date',
  'map_slipped_milestones',
  'map_last_nudge_at',
  'map_slack_connect_channel_id',
];
const DEAL_CORE_PROPERTIES = ['dealname', 'amount', 'closedate', 'dealstage', 'pipeline', 'hubspot_owner_id', 'hs_is_closed', 'deal_currency_code'];
const CONTACT_PROPERTIES = ['firstname', 'lastname', 'jobtitle', 'email', 'hs_buying_role'];

function milestonePropertyNames(template) {
  return template.flatMap((m) => [`map_${m.key}_date`, `map_${m.key}_done`]);
}

function dealPropertiesToRead(template) {
  return [...DEAL_CORE_PROPERTIES, ...MAP_SUMMARY_PROPERTIES, ...milestonePropertyNames(template)];
}

function hubspotDealUrl(appBaseUrl, portalId, dealId) {
  if (isPlaceholderSetting(portalId) || !/^\d+$/.test(String(portalId)) || !/^\d+$/.test(String(dealId))) return null;
  return `${String(appBaseUrl).replace(/\/+$/, '')}/contacts/${portalId}/record/0-3/${dealId}`;
}

/** Synthetic bundle for offline simulation: values come from the webhook payload when present. */
function offlineDealBundle(dealId, payload = {}) {
  const props = payload.properties && typeof payload.properties === 'object' ? payload.properties : {};
  const value = (k) => (props[k] && typeof props[k] === 'object' && 'value' in props[k] ? props[k].value : props[k]);
  const offline = payload.offline || {};
  return {
    deal: {
      id: String(dealId),
      properties: {
        dealname: value('dealname') || 'Offline Simulation Deal',
        amount: value('amount') || null,
        closedate: value('closedate') || null,
        dealstage: value('dealstage') || null,
        pipeline: value('pipeline') || 'default',
        hubspot_owner_id: value('hubspot_owner_id') || null,
        hs_is_closed: 'false',
        deal_currency_code: value('deal_currency_code') || 'USD',
        map_document_url: value('map_document_url') || null,
        map_status: value('map_status') || null,
      },
    },
    company: offline.company || { id: 'offline-company', name: 'Example Customer Inc.' },
    contacts: Array.isArray(offline.contacts) ? offline.contacts : [],
    owner: offline.owner || { id: 'offline-owner', firstName: 'Alex', lastName: 'Rivera' },
  };
}

function createMapHubSpotClient({
  token,
  dryRun = true,
  sandboxMode = true,
  sandboxPortalId = '',
  baseUrl = 'https://api.hubapi.com',
  fetchImpl = globalThis.fetch,
  sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
  offlineDeals = [],
}) {
  const offline = isPlaceholderSetting(token);
  const apiBase = String(baseUrl).replace(/\/+$/, '');
  const audit = [];
  let sandboxCheck = null;

  async function call(method, path, body, { allow404 = false } = {}) {
    if (offline) throw new HubSpotSafetyError('hubspot_offline', 'HubSpot token is a placeholder; live API calls are disabled');
    for (let attempt = 0; ; attempt += 1) {
      const response = await fetchImpl(`${apiBase}${path}`, {
        method,
        headers: { authorization: `Bearer ${token}`, 'content-type': 'application/json' },
        body: body === undefined ? undefined : JSON.stringify(body),
      });
      if (response.status === 404 && allow404) return null;
      if ((response.status === 429 || response.status >= 500) && attempt < 3) {
        const retryAfter = Number(response.headers && response.headers.get ? response.headers.get('retry-after') : NaN);
        await sleep(Math.min(Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter * 1000 : 500 * 2 ** attempt, 10000));
        continue;
      }
      if (!response.ok) throw new HubSpotRequestError(`HubSpot ${method} ${path.split('?')[0]} failed with HTTP ${response.status}`, response.status);
      const text = await response.text();
      return text ? JSON.parse(text) : {};
    }
  }

  async function verifySandbox() {
    if (!sandboxCheck) {
      sandboxCheck = (async () => {
        const details = await call('GET', '/account-info/v3/details');
        const portalId = String(details && details.portalId !== undefined ? details.portalId : '');
        const accountType = String((details && details.accountType) || '').toUpperCase();
        if (!isPlaceholderSetting(sandboxPortalId)) {
          if (portalId !== String(sandboxPortalId)) {
            throw new HubSpotSafetyError('sandbox_portal_mismatch', 'SANDBOX_MODE=true but the token belongs to a portal other than HUBSPOT_SANDBOX_PORTAL_ID');
          }
        } else if (!['SANDBOX', 'DEVELOPER_TEST'].includes(accountType)) {
          throw new HubSpotSafetyError('sandbox_account_required', `SANDBOX_MODE=true but the account type is "${accountType || 'unknown'}"`);
        }
        return { portalId, accountType };
      })();
    }
    return sandboxCheck;
  }

  async function getDealBundle(dealId, { properties, payload } = {}) {
    if (offline) return offlineDealBundle(dealId, payload);
    const deal = await call(
      'GET',
      `/crm/v3/objects/deals/${encodeURIComponent(dealId)}?properties=${encodeURIComponent(properties.join(','))}&associations=companies,contacts`,
      undefined,
      { allow404: true },
    );
    if (!deal) return null;
    const assoc = (type) => ((deal.associations && deal.associations[type] && deal.associations[type].results) || []).map((r) => String(r.id));
    const [companyIds, contactIds] = [assoc('companies'), assoc('contacts')];
    let company = null;
    if (companyIds.length) {
      const companies = await call('POST', '/crm/v3/objects/companies/batch/read', { properties: ['name', 'domain'], inputs: [{ id: companyIds[0] }] });
      const c = companies && companies.results && companies.results[0];
      company = c ? { id: c.id, name: c.properties.name, domain: c.properties.domain } : null;
    }
    let contacts = [];
    if (contactIds.length) {
      const result = await call('POST', '/crm/v3/objects/contacts/batch/read', { properties: CONTACT_PROPERTIES, inputs: contactIds.slice(0, 50).map((id) => ({ id })) });
      contacts = ((result && result.results) || []).map((c) => ({ id: c.id, ...c.properties }));
    }
    let owner = null;
    const ownerId = deal.properties && deal.properties.hubspot_owner_id;
    if (ownerId) {
      const o = await call('GET', `/crm/v3/owners/${encodeURIComponent(ownerId)}`, undefined, { allow404: true });
      owner = o ? { id: String(o.id), firstName: o.firstName || '', lastName: o.lastName || '' } : null;
    }
    return { deal: { id: String(deal.id), properties: deal.properties || {} }, company, contacts, owner };
  }

  async function searchActiveMapDeals({ properties, maxDeals = 500 }) {
    if (offline) return offlineDeals.slice(0, maxDeals);
    const deals = [];
    let after;
    do {
      const body = {
        filterGroups: [{ filters: [{ propertyName: 'map_status', operator: 'EQ', value: 'active' }] }],
        properties,
        limit: 100,
        sorts: [{ propertyName: 'closedate', direction: 'ASCENDING' }],
      };
      if (after) body.after = after;
      const page = await call('POST', '/crm/v3/objects/deals/search', body);
      for (const d of (page && page.results) || []) deals.push({ id: String(d.id), properties: d.properties || {} });
      after = page && page.paging && page.paging.next ? page.paging.next.after : undefined;
    } while (after && deals.length < maxDeals);
    return deals.slice(0, maxDeals);
  }

  async function updateDeal(dealId, properties) {
    if (!properties || !Object.keys(properties).length) return { mode: 'skipped' };
    if (dryRun) {
      const record = { mode: 'intercepted_dry_run', method: 'PATCH', path: `/crm/v3/objects/deals/${dealId}`, properties };
      audit.push(record);
      return record;
    }
    if (sandboxMode) await verifySandbox();
    await call('PATCH', `/crm/v3/objects/deals/${encodeURIComponent(dealId)}`, { properties });
    audit.push({ mode: 'written', method: 'PATCH', path: `/crm/v3/objects/deals/${dealId}` });
    return { mode: 'written', environment: sandboxMode ? 'sandbox' : 'production' };
  }

  return { offline, getDealBundle, searchActiveMapDeals, updateDeal, verifySandbox, auditLog: () => audit.slice() };
}

// ---- src/core/slack.js ----
/**
 * Slack messages (MAP created, internal slip alert, client nudge) and a sender
 * with the same interlocks as the CRM client:
 *   DRY_RUN=true      -> message returned, never sent
 *   SANDBOX_MODE=true -> every message (including client nudges) goes to the
 *                        sandbox channel / webhook only
 * Client nudges go to a Slack Connect channel ID stored on the deal, and only
 * when CLIENT_NUDGES_ENABLED=true.
 */

class SlackSafetyError extends Error {
  constructor(code, message) {
    super(message || code);
    this.name = 'SlackSafetyError';
    this.code = code;
  }
}

function slackEscape(value) {
  return String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

function modeTag(config) {
  if (config.dryRun) return '[DRY RUN] ';
  if (config.sandboxMode) return '[SANDBOX] ';
  return '';
}

function link(url, label) {
  return url && /^https:\/\//.test(url) ? `<${url}|${slackEscape(label)}>` : slackEscape(label);
}

function ownerMention(config, ownerId) {
  const slackId = ownerId ? config.slack.ownerSlackMap[String(ownerId)] : null;
  return slackId && /^[UW][A-Z0-9]{5,}$/.test(slackId) ? `<@${slackId}>` : null;
}

function buildMapCreatedMessage({ model, documentUrl, dealUrl, ownerId, config }) {
  const lines = model.milestones.map((m) => `• *${slackEscape(m.name)}*: ${slackEscape(m.targetDateLabel)} (${slackEscape(m.ownerLabel)})`).join('\n');
  const mention = ownerMention(config, ownerId);
  return {
    kind: 'map_created',
    text: `${modeTag(config)}Mutual Action Plan ready for ${model.dealName}`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: `${modeTag(config)}MAP ready: ${model.dealName}`.slice(0, 150) } },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${mention ? `${mention} ` : ''}${link(documentUrl, 'Open the Mutual Action Plan')} · ${link(dealUrl, 'HubSpot deal')}\nTarget close: *${slackEscape(model.closeDate)}*${model.compressed ? '\n:warning: Short runway: milestones were compressed. Confirm the dates at kickoff.' : ''}`,
        },
      },
      { type: 'section', text: { type: 'mrkdwn', text: lines.slice(0, 2900) } },
    ],
  };
}

function buildSlipAlertMessage({ deal, evaluation, dealUrl, config }) {
  const p = deal.properties;
  const mention = ownerMention(config, p.hubspot_owner_id);
  const fmt = (i) => `• *${slackEscape(i.name)}* (${i.owner === 'internal' ? 'internal' : i.owner === 'both' ? 'joint' : 'client'}): due ${slackEscape(i.targetDate)}, ${i.daysLate} business day${i.daysLate === 1 ? '' : 's'} late`;
  const soon = evaluation.dueSoon.map((i) => `• ${slackEscape(i.name)}: due ${slackEscape(i.targetDate)}`).join('\n');
  return {
    kind: 'slip_alert',
    text: `${modeTag(config)}${evaluation.slipped.length} MAP milestone(s) slipped on ${p.dealname || `deal ${deal.id}`}`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: `${modeTag(config)}MAP slipping: ${p.dealname || `Deal ${deal.id}`}`.slice(0, 150) } },
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${mention ? `${mention} ` : ''}${evaluation.slipped.map(fmt).join('\n')}`.slice(0, 2900),
        },
      },
      ...(soon ? [{ type: 'section', text: { type: 'mrkdwn', text: `*Due soon*\n${soon}`.slice(0, 2900) } }] : []),
      {
        type: 'context',
        elements: [{ type: 'mrkdwn', text: `${link(p.map_document_url, 'MAP')} · ${link(dealUrl, 'HubSpot deal')} · close date ${slackEscape(String(p.closedate || '').slice(0, 10) || 'n/a')}` }],
      },
    ],
  };
}

function buildClientNudgeMessage({ deal, evaluation, config }) {
  const p = deal.properties;
  const items = evaluation.clientSlipped.map((i) => `• *${slackEscape(i.name)}* (planned for ${slackEscape(i.targetDate)})`).join('\n');
  return {
    kind: 'client_nudge',
    text: `${modeTag(config)}Quick check-in on the shared plan`,
    blocks: [
      {
        type: 'section',
        text: {
          type: 'mrkdwn',
          text: `${modeTag(config)}Hi all, a quick check-in on the shared plan. These steps were planned for earlier dates and still show as open:\n${items}\n\nIf any of them is done, or the date needs to move, reply here and I'll update the plan. ${link(p.map_document_url, 'Open the plan')}`.slice(0, 2900),
        },
      },
    ],
  };
}

function validWebhook(url) {
  return !isPlaceholderSetting(url) && String(url).startsWith('https://hooks.slack.com/');
}

function validChannel(id) {
  return !isPlaceholderSetting(id) && /^[CGD][A-Z0-9]{6,}$/.test(String(id));
}

function createMapSlackClient({ config, fetchImpl = globalThis.fetch }) {
  const s = config.slack;
  const hasBot = !isPlaceholderSetting(s.botToken);

  function resolveTarget(channelOverride) {
    if (config.sandboxMode) {
      if (hasBot && validChannel(s.sandboxChannelId)) return { type: 'api', channel: s.sandboxChannelId, environment: 'sandbox' };
      if (validWebhook(s.sandboxWebhookUrl)) return { type: 'webhook', url: s.sandboxWebhookUrl, environment: 'sandbox' };
      throw new SlackSafetyError('slack_sandbox_target_missing', 'SANDBOX_MODE=true requires SLACK_SANDBOX_CHANNEL_ID (with SLACK_BOT_TOKEN) or SLACK_SANDBOX_WEBHOOK_URL');
    }
    if (channelOverride) {
      if (hasBot && validChannel(channelOverride)) return { type: 'api', channel: channelOverride, environment: 'production' };
      return null;
    }
    if (hasBot && validChannel(s.channelId)) return { type: 'api', channel: s.channelId, environment: 'production' };
    if (validWebhook(s.webhookUrl)) return { type: 'webhook', url: s.webhookUrl, environment: 'production' };
    return null;
  }

  async function send(message, { channelOverride = null } = {}) {
    if (config.dryRun) return { mode: 'intercepted_dry_run', kind: message.kind, environment: config.sandboxMode ? 'sandbox' : 'production' };
    const target = resolveTarget(channelOverride);
    if (!target) return { mode: 'not_configured', kind: message.kind };
    const payload = { text: message.text, blocks: message.blocks };
    if (target.type === 'webhook') {
      const response = await fetchImpl(target.url, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(payload) });
      if (!response.ok) throw new Error(`Slack webhook returned HTTP ${response.status}`);
      return { mode: 'sent', kind: message.kind, environment: target.environment, via: 'webhook' };
    }
    const response = await fetchImpl('https://slack.com/api/chat.postMessage', {
      method: 'POST',
      headers: { 'content-type': 'application/json; charset=utf-8', authorization: `Bearer ${s.botToken}` },
      body: JSON.stringify({ channel: target.channel, ...payload, unfurl_links: false }),
    });
    const body = JSON.parse((await response.text()) || '{}');
    if (!response.ok || body.ok !== true) throw new Error(`Slack chat.postMessage failed: ${body.error || response.status}`);
    return { mode: 'sent', kind: message.kind, environment: target.environment, via: 'chat.postMessage' };
  }

  return { send, resolveTarget };
}

// ---- src/core/pipeline.js ----
/**
 * Stages shared by the Node.js runtime (src/index.js) and the n8n workflow.
 *
 * Generation (webhook): ingest -> loadDeal -> plan -> document -> crmSync -> notify -> finalize
 * Monitoring (weekly):  monitorCollect -> monitorAct (per deal)
 *
 * Every stage takes and returns JSON-serializable data. Generation stages skip
 * themselves once the status is no longer "accepted", so any failure flows
 * straight to the response.
 */

function createMapClients(config, { fetchImpl, sleep, offlineDeals } = {}) {
  return {
    hubspot: createMapHubSpotClient({
      token: config.hubspot.token,
      dryRun: config.dryRun,
      sandboxMode: config.sandboxMode,
      sandboxPortalId: config.hubspot.sandboxPortalId,
      baseUrl: config.hubspot.baseUrl,
      fetchImpl,
      ...(sleep ? { sleep } : {}),
      ...(offlineDeals ? { offlineDeals } : {}),
    }),
    slack: createMapSlackClient({ config, fetchImpl }),
  };
}

function headerValue(headers, name) {
  for (const [k, v] of Object.entries(headers || {})) if (k.toLowerCase() === name) return Array.isArray(v) ? v[0] : v;
  return null;
}

function secretsMatch(a, b) {
  const x = Buffer.from(String(a || ''));
  const y = Buffer.from(String(b || ''));
  return x.length === y.length && x.length > 0 && crypto.timingSafeEqual(x, y);
}

/** Accepts HubSpot workflow webhooks (objectId / hs_object_id) and app webhook event arrays. */
function extractDealId(payload) {
  const candidates = [];
  const pick = (p) => {
    if (!p || typeof p !== 'object') return;
    candidates.push(p.dealId, p.objectId, p.hs_object_id);
    const props = p.properties || {};
    const hsId = props.hs_object_id;
    candidates.push(hsId && typeof hsId === 'object' ? hsId.value : hsId);
  };
  if (Array.isArray(payload)) payload.filter((e) => !e.subscriptionType || String(e.subscriptionType).startsWith('deal.')).forEach(pick);
  else pick(payload);
  const found = candidates.find((c) => c !== undefined && c !== null && /^\d{1,20}$/.test(String(c)));
  return found ? String(found) : null;
}

function stop(ctx, status, httpStatus, reason, error) {
  return { ...ctx, status, httpStatus, reason, error: error ? String(error).slice(0, 300) : null };
}

async function ingestMapStage(input, { config, now = Date.now() }) {
  const base = { status: 'accepted', httpStatus: 200, reason: null, receivedAt: new Date(now).toISOString(), dryRun: config.dryRun, sandboxMode: config.sandboxMode, warnings: [] };
  const check = validateMapConfig(config);
  if (check.errors.length) return stop({ ...base, errors: check.errors }, 'failed', 500, 'config_invalid');
  base.warnings = check.warnings;
  const raw = typeof input.rawBody === 'string' ? input.rawBody : JSON.stringify(input.body ?? {});
  if (Buffer.byteLength(raw, 'utf8') > config.webhook.maxBodyBytes) return stop(base, 'rejected', 413, 'payload_too_large');
  if (!isPlaceholderSetting(config.webhook.secret)) {
    if (!secretsMatch(headerValue(input.headers, config.webhook.secretHeader), config.webhook.secret)) return stop(base, 'rejected', 401, 'invalid_webhook_secret');
  }
  let payload;
  try {
    payload = typeof input.rawBody === 'string' ? JSON.parse(input.rawBody) : input.body;
  } catch {
    return stop(base, 'rejected', 400, 'invalid_json');
  }
  const dealId = extractDealId(payload);
  if (!dealId) return stop(base, 'rejected', 422, 'deal_id_missing');
  const keep = Array.isArray(payload) ? {} : { properties: payload.properties, offline: payload.offline, force: payload.force === true };
  return { ...base, dealId, payload: keep };
}

async function loadDealStage(ctx, { config, hubspot }) {
  if (ctx.status !== 'accepted') return ctx;
  try {
    const bundle = await hubspot.getDealBundle(ctx.dealId, { properties: dealPropertiesToRead(config.schedule.template), payload: ctx.payload });
    if (!bundle) return stop(ctx, 'ignored', 404, 'deal_not_found');
    const p = bundle.deal.properties;
    const stageOk = !p.dealstage || config.trigger.stageIds.includes(String(p.dealstage));
    if (!stageOk) return stop({ ...ctx, bundle }, 'ignored', 200, 'stage_not_targeted');
    if (String(p.hs_is_closed) === 'true') return stop({ ...ctx, bundle }, 'ignored', 200, 'deal_closed');
    if (p.map_document_url && p.map_status === 'active' && !config.trigger.regenerateExisting && !ctx.payload.force) {
      return stop({ ...ctx, bundle }, 'ignored', 200, 'map_already_exists');
    }
    return { ...ctx, bundle };
  } catch (err) {
    return stop(ctx, 'failed', err.code === 'sandbox_portal_mismatch' || err.code === 'sandbox_account_required' ? 503 : 502, `hubspot_read_${err.code || 'error'}`, err.message);
  }
}

async function planStage(ctx, { config, now = Date.now() }) {
  if (ctx.status !== 'accepted') return ctx;
  const { deal, company, contacts, owner } = ctx.bundle;
  const todayIso = new Date(now).toISOString().slice(0, 10);
  try {
    const plan = scheduleMilestones({
      template: config.schedule.template,
      startIso: todayIso,
      closeIso: toIsoDate(deal.properties.closedate),
      holidays: config.schedule.holidays,
      minRunwayBusinessDays: config.schedule.minRunwayBusinessDays,
    });
    const stakeholders = resolveStakeholders(contacts);
    const model = buildMapModel({ deal, company, owner, plan, stakeholders, config, generatedAt: new Date(now).toISOString() });
    const warnings = [...ctx.warnings];
    if (plan.shortRunway) warnings.push(`Only ${plan.runwayBusinessDays} business days until close`);
    if (!contacts.length) warnings.push('No contacts associated with the deal: customer owners are "To be confirmed"');
    return { ...ctx, plan, model, warnings };
  } catch (err) {
    if (err instanceof PlanError) return stop(ctx, 'failed', 422, `plan_${err.code}`, err.message);
    throw err;
  }
}

async function documentStage(ctx, { config, fetchImpl }) {
  if (ctx.status !== 'accepted') return ctx;
  try {
    const document = await createMapDocument(ctx.model, { config, fetchImpl });
    return { ...ctx, document };
  } catch (err) {
    return stop(ctx, 'failed', err.code && /missing|invalid/.test(err.code) ? 503 : 502, `document_${err.code || 'error'}`, err.message);
  }
}

function buildMapDealProperties(ctx) {
  const props = {
    map_document_url: ctx.document.url,
    map_status: 'active',
    map_generated_at: ctx.model.generatedAt,
    map_slipped_milestones: '',
  };
  for (const m of ctx.plan.milestones) {
    props[`map_${m.key}_date`] = m.targetDate;
    props[`map_${m.key}_done`] = 'false';
  }
  const next = ctx.plan.milestones[0];
  props.map_next_milestone = next ? next.name : '';
  props.map_next_milestone_date = next ? next.targetDate : '';
  return props;
}

async function crmSyncStage(ctx, { hubspot }) {
  if (ctx.status !== 'accepted') return ctx;
  const properties = buildMapDealProperties(ctx);
  try {
    const result = await hubspot.updateDeal(ctx.dealId, properties);
    return { ...ctx, crm: { mode: result.mode, environment: result.environment || null, properties } };
  } catch (err) {
    return stop({ ...ctx, crm: { mode: 'error', properties } }, 'failed', err.code && err.code.startsWith('sandbox') ? 503 : 502, `hubspot_write_${err.code || 'error'}`, err.message);
  }
}

async function notifyMapStage(ctx, { config, slack }) {
  const created = ctx.status === 'accepted' && ctx.document;
  if (!created || !config.slack.announceNewMaps) return { ...ctx, slack: { mode: 'skipped' } };
  const message = buildMapCreatedMessage({
    model: ctx.model,
    documentUrl: ctx.document.url,
    dealUrl: hubspotDealUrl(config.hubspot.appBaseUrl, config.hubspot.portalId, ctx.dealId),
    ownerId: ctx.bundle.deal.properties.hubspot_owner_id,
    config,
  });
  try {
    return { ...ctx, slack: await slack.send(message) };
  } catch (err) {
    return { ...ctx, slack: { mode: 'error', code: err.code || null }, warnings: [...ctx.warnings, `Slack: ${String(err.message).slice(0, 200)}`] };
  }
}

function finalizeMapStage(ctx) {
  const status = ctx.status === 'accepted' ? 'generated' : ctx.status;
  return {
    httpStatus: ctx.httpStatus,
    body: {
      status,
      reason: ctx.reason || null,
      error: ctx.error || null,
      errors: ctx.errors || [],
      dryRun: ctx.dryRun,
      sandboxMode: ctx.sandboxMode,
      dealId: ctx.dealId || null,
      compressed: ctx.plan ? ctx.plan.compressed : null,
      milestones: ctx.plan ? ctx.plan.milestones.map((m) => ({ key: m.key, name: m.name, targetDate: m.targetDate, owner: m.owner })) : null,
      document: ctx.document ? { provider: ctx.document.provider, mode: ctx.document.mode, url: ctx.document.url } : null,
      crm: ctx.crm ? { mode: ctx.crm.mode, properties: ctx.dryRun ? ctx.crm.properties : undefined } : null,
      slack: ctx.slack || null,
      warnings: ctx.warnings || [],
    },
    preview: ctx.document && ctx.document.markdown ? ctx.document.markdown : null,
  };
}

/** Node.js mirror of the generation branch of the n8n workflow. */
async function generateMap(input, { config, fetchImpl = globalThis.fetch, clients, now = () => Date.now() }) {
  const { hubspot, slack } = clients || createMapClients(config, { fetchImpl });
  let ctx = await ingestMapStage(input, { config, now: now() });
  ctx = await loadDealStage(ctx, { config, hubspot });
  ctx = await planStage(ctx, { config, now: now() });
  ctx = await documentStage(ctx, { config, fetchImpl });
  ctx = await crmSyncStage(ctx, { hubspot });
  ctx = await notifyMapStage(ctx, { config, slack });
  return finalizeMapStage(ctx);
}

async function monitorCollectStage({ config, hubspot, now = Date.now() }) {
  const check = validateMapConfig(config);
  if (check.errors.length) return { status: 'failed', reason: 'config_invalid', errors: check.errors, items: [] };
  const todayIso = new Date(now).toISOString().slice(0, 10);
  const properties = dealPropertiesToRead(config.schedule.template);
  const deals = await hubspot.searchActiveMapDeals({ properties, maxDeals: config.monitor.maxDeals });
  const cooldownMs = config.monitor.nudgeCooldownDays * 24 * 3600 * 1000;
  const items = deals.map((deal) => {
    const evaluation = evaluateMilestones({
      dealProperties: deal.properties,
      template: config.schedule.template,
      todayIso,
      holidays: config.schedule.holidays,
      dueSoonBusinessDays: config.monitor.dueSoonBusinessDays,
    });
    const lastNudge = Date.parse(deal.properties.map_last_nudge_at || '');
    return {
      todayIso,
      deal: { id: String(deal.id), properties: deal.properties },
      evaluation,
      closed: String(deal.properties.hs_is_closed) === 'true',
      inCooldown: Number.isFinite(lastNudge) && now - lastNudge < cooldownMs,
    };
  });
  return { status: 'collected', todayIso, items, warnings: check.warnings };
}

async function monitorActStage(item, { config, hubspot, slack, now = Date.now() }) {
  if (!item || !item.deal) return { skipped: true, status: (item && item.status) || 'no_deal', reason: (item && item.reason) || null };
  const { deal, evaluation } = item;
  const result = { dealId: deal.id, slipped: evaluation.slipped.map((i) => i.key), alert: null, clientNudge: null, crm: null, notes: [] };
  const props = {};
  if (item.closed || evaluation.allDone) {
    props.map_status = 'completed';
    result.notes.push(item.closed ? 'deal closed: MAP marked completed' : 'all milestones done: MAP marked completed');
  } else {
    props.map_next_milestone = evaluation.next ? evaluation.next.name : '';
    props.map_next_milestone_date = evaluation.next ? evaluation.next.targetDate : '';
    props.map_slipped_milestones = evaluation.slipped.map((i) => i.name).join('; ');
    if (evaluation.slipped.length && item.inCooldown) result.notes.push('nudge skipped: cooldown');
    if (evaluation.slipped.length && !item.inCooldown) {
      const dealUrl = hubspotDealUrl(config.hubspot.appBaseUrl, config.hubspot.portalId, deal.id);
      try {
        result.alert = await slack.send(buildSlipAlertMessage({ deal, evaluation, dealUrl, config }));
      } catch (err) {
        result.alert = { mode: 'error', code: err.code || null };
      }
      const channel = deal.properties.map_slack_connect_channel_id;
      if (config.slack.clientNudgesEnabled && evaluation.clientSlipped.length && channel) {
        try {
          result.clientNudge = await slack.send(buildClientNudgeMessage({ deal, evaluation, config }), { channelOverride: channel });
        } catch (err) {
          result.clientNudge = { mode: 'error', code: err.code || null };
        }
      } else if (evaluation.clientSlipped.length) {
        result.clientNudge = { mode: config.slack.clientNudgesEnabled ? 'no_shared_channel' : 'disabled' };
      }
      if (result.alert && ['sent', 'intercepted_dry_run'].includes(result.alert.mode)) props.map_last_nudge_at = new Date(now).toISOString();
    }
  }
  try {
    result.crm = await hubspot.updateDeal(deal.id, props);
  } catch (err) {
    result.crm = { mode: 'error', code: err.code || null };
  }
  result.properties = props;
  return result;
}

/** Node.js mirror of the monitoring branch of the n8n workflow. */
async function runMonitor({ config, fetchImpl = globalThis.fetch, clients, now = () => Date.now() }) {
  const { hubspot, slack } = clients || createMapClients(config, { fetchImpl });
  const collected = await monitorCollectStage({ config, hubspot, now: now() });
  const results = [];
  for (const item of collected.items) results.push(await monitorActStage(item, { config, hubspot, slack, now: now() }));
  return {
    status: collected.status,
    reason: collected.reason || null,
    dryRun: config.dryRun,
    sandboxMode: config.sandboxMode,
    today: collected.todayIso || null,
    dealsChecked: collected.items.length,
    dealsSlipping: results.filter((r) => r.slipped.length).length,
    results,
    errors: collected.errors || [],
  };
}

// ---- n8n stage runner ----
const env = $env;
const config = loadMapConfig(env);
const n8nHelpers = this.helpers;
const n8nSleep = (ms) => new Promise((resolve) => (typeof setTimeout === 'function' ? setTimeout(resolve, ms) : resolve()));
const n8nFetch = async (url, init = {}) => {
  const response = await n8nHelpers.httpRequest({
    url,
    method: init.method || 'GET',
    headers: init.headers || {},
    body: init.body,
    json: false,
    returnFullResponse: true,
    ignoreHttpStatusErrors: true,
    timeout: 30000,
  });
  const raw = response.body;
  const text = typeof raw === 'string' ? raw : Buffer.isBuffer(raw) ? raw.toString('utf8') : raw == null ? '' : JSON.stringify(raw);
  return {
    ok: response.statusCode >= 200 && response.statusCode < 300,
    status: response.statusCode,
    headers: { get: (name) => (response.headers || {})[String(name).toLowerCase()] ?? null },
    text: async () => text,
    json: async () => JSON.parse(text),
  };
};
const clients = createMapClients(config, { fetchImpl: n8nFetch, sleep: n8nSleep });

